    // the thing drawn was "60 GOLD", so the name was cut to leave room for two characters and then ran into
    // seven - which is how THE ADVENTURE BEGINS ended up lying across its own price.
    /* A PRICE IS A NUMBER AND ITS COIN: the words GOLD and SILVER took seven letters off every name in the row */
    const priced = !k.practice && !eq && !owned && !locked && k.price > 0, ic = priced ? (k.silver ? PROP.silver[0] : PROP.coin[0]) : null, icw = ic ? ic.width + 2 : 0;
    const bg = k.practice ? 'ENTER' : eq ? 'EQUIPPED' : owned ? 'OWNED' : locked ? 'LOCKED' : k.price === 0 ? 'FREE' : String(k.price);
    rowName(bg, icw);
    if (ic) g.drawImage(ic, listX + listW - 3 - ic.width, yy + 2 - (ic.height >> 1));
    text(bg, listX + listW - 4 - icw, yy, eq ? UI.sel : owned ? UI.dim : locked ? '#6a6a7a' : ((k.silver ? (silverAvail() >= k.price || (coinRoute(k) && PROG.coins >= k.coinPrice)) : PROG.coins >= k.price) ? (k.silver ? UI.silver : UI.gold) : '#ff6b6b'), 'right', 6);
  });
  // ---- the panel: what it looks like on you, what it costs, and the whole of what it does ----
  g.fillStyle = 'rgba(20,16,30,0.6)'; g.fillRect(pvX, pvY, pvW, pvH);
  g.strokeStyle = 'rgba(255,255,255,0.12)'; g.strokeRect(pvX + 0.5, pvY + 0.5, pvW - 1, pvH - 1);
  { const k = items[storeI]; const mx = pvX + pvW / 2;
    if (k) {
      const st = storeRowState(tab, k), owned = st === 'owned' || st === 'equipped', eq = st === 'equipped', locked = st === 'locked', lockWhy = lockOf(k, PROG, featDone);
      // the art sits in the top 46px, feet on that line - unless the words need the room: then the art shrinks and
      // the words move up (the WISP's line ran off the bottom of the box)
      const body0 = locked ? lockWhy : (k.desc || k.per || '');
      const need = 8 * Math.min(2, wrap(k.name, pvW - 10, 6).length) + 11 + BODY_LH * wrap(body0, pvW - 10, 6).length, room = pvH - 10 - 50;
      const squeeze = Math.max(0, Math.min(24, need - room)), artB = pvY + 46 - squeeze;
      if (tab.key === 'skin' || tab.key === 'sword' || tab.key === 'hero') {
        const set = tab.key === 'hero' ? preview('hero:' + k.id + ':' + PROG.skin + ':' + PROG.sword, () => heroSet(PROG.skin, PROG.sword, 'idle', k.id))
          : tab.key === 'skin' ? skinPreview(k)
          : weaponPreview(k);
        const fr = tab.key === 'sword' ? set.R.atk[Math.floor(time * 6) % 2 + 1] : set.R.idle[Math.floor(time * 4.5) % set.R.idle.length];
        const sc = Math.max(1, Math.min(3, (46 - squeeze) / fr.height)); g.drawImage(fr, 0, 0, fr.width, fr.height, Math.round(mx - fr.width * sc / 2), Math.round(artB - fr.height * sc), Math.round(fr.width * sc), Math.round(fr.height * sc));
      } else {
        const icon = iconOf(k);
        const isc = squeeze > 8 ? 2 : 3; if (icon) g.drawImage(icon, 0, 0, icon.width, icon.height, Math.round(mx - icon.width * isc / 2), Math.round(artB - icon.height * isc), icon.width * isc, icon.height * isc);
        if (tab.key === 'menu') text('~ ~', mx, pvY + 30, UI.dim, 'center');
      }
      let ty = pvY + 50 - squeeze;
      for (const ln of wrap(k.name, pvW - 10, 6).slice(0, 2)) { text(ln, mx, ty, UI.title, 'center', 6); ty += 8; }
      // what it costs, or what you already have
      const cost = k.consumable ? (PROG.flaskUp || 0) + ' OF ' + k.max + ' MADE'
        : tab.key === 'hero' && (eq || owned) ? (eq ? 'EQUIPPED  L' : 'OWNED  L') + heroLevel(k.id)   /* a hero carries his own level now: the card has to say which */
        : k.practice ? 'Z TO STEP THROUGH' : eq ? 'EQUIPPED' : owned ? 'OWNED' : locked ? 'LOCKED' : k.price === 0 ? 'FREE' : k.price + (k.silver ? ' SILVER' : ' GOLD') + (coinRoute(k) ? ' OR ' + k.coinPrice + ' GOLD' : '');
      text(cost, mx, ty, eq || owned ? UI.sel : locked ? '#ff9a5c' : k.silver ? UI.silver : UI.gold, 'center', 6); ty += 11;
      const body = locked ? lockWhy : (k.desc || k.per || '');
      /* THE WHOLE OF WHAT IT DOES, A PAGE AT A TIME: a hero's description ran to thirty lines and the panel showed the first eight */
      const bl = wrap(body, pvW - 10, 6), per = Math.max(1, Math.floor((pvY + pvH - 12 - ty) / BODY_LH)), pages = Math.max(1, Math.ceil(bl.length / per)), pg = storePage % pages; storePages = pages;
      if (pages > 1 && window.__textRec) textRec('paged', { s: body, pages });
      bl.slice(pg * per, pg * per + per).forEach((ln, i) => text(ln, pvX + 5, ty + i * BODY_LH, locked ? '#ff9a5c' : UI.text, 'left', 6));
      if (pages > 1) text(moreKey() + ' MORE ' + (pg + 1) + '/' + pages, pvX + pvW - 5, pvY + pvH - 10, UI.sel, 'right', 6);
    } else storePages = 1; }
  text(storeMsgT > 0 ? storeMsg : fitName(loadoutSafe() ? STORE_HELP.buy : STORE_HELP.look, w - 16, 6), VW / 2, y + h - 10, storeMsgT > 0 ? UI.title : UI.dim, 'center', 6);
}

// ---------- bestiary ----------
const BEASTS = [
 { t: 'oathblade', name: 'ROAD WARDEN DUELIST', sub: 'a knight of the Road Wardens', desc: 'Sword and shield. He guards his front - go round, or put weight through it - and answers a mash with a riposte. His CUT glints on the beat: guard on the glint and he is yours. His shield goes up over his helm against a plunge (GUARDS HIGH): go low. And a LUNGE from further off.' },   /* (claude/order) THE ROAD WARDENS's four bodies (src/order-knights.js); each chapter wears its own skin and name */
 { t: 'oathmaul', name: 'ROAD WARDEN BRUTE', sub: 'a knight of the Road Wardens', desc: 'A greatmaul. Nothing throws him until his poise breaks. The SLAM is red: be out from under it, and the maul stays in the floor - his opening. The SWEEP a shield turns. Come down on him and he CATCHES you out of the air.' },
 { t: 'oathlance', name: 'ROAD WARDEN LANCER', sub: 'a knight of the Road Wardens', desc: 'A war lance and the reach to use it. The THRUST and the CHARGE a shield turns - and a turned charge rebounds him. Dodge it and he runs on: into a wall he is dazed, at a ledge he TEETERS (throw him off). Over his head he thrusts straight up: bait it, land beside him.' },
 { t: 'oathmage', name: 'ROAD WARDEN BATTLE MAGE', sub: 'a knight of the Road Wardens', desc: 'A blade and a focus. He CASTS his chapter element from mid range: a shield turns it, a parry sends it back at him, and a blow while he casts INTERRUPTS him. His ward turns a shot off his front: dash through it. Up close, a short BLADE.' },
 { t: 'familiar', name: 'THE FAMILIAR', sub: 'loose in the falling tower', desc: 'Guard the claw and rushing dash, jump the red low slam, and guard or dodge the aimed spit and three-shot fan. Each attack leaves the eye exposed. It holds the library door on the return route.' },
 { t: 'lanternshade', name: 'THE LANTERN SHADE', sub: 'a light without a keeper', desc: 'The ghost marks your feet with a pale ring. Step clear or guard the yellow flash. Its lantern dims after it strikes: close in then.' },
 { t: 'bonegob', name: 'THE BONE GOBLIN', sub: 'it kept the arm', desc: 'A goblin that has been under the hill long enough to lose the rest of itself. It will not come to you: it backs off and throws its own skull, which is the only thing in these caverns that can reach you across a room. Close on it, or take the skull.' },
 { t: 'husk', name: 'THE GRAVE HUSK', sub: 'swollen with the hill', desc: 'The second thing the caverns raise: slower than a zombie, twice the man to put down, and full of gas. It bursts when it dies, and a husk killed at arm’s length poisons you as surely as the green water does.' },
 { t: 'apprentice', name: 'THE DEAD APPRENTICE', sub: 'still at his lesson', desc: 'One of the tower’s own, up again in the robe he died in. He walks like the rest of the dead, but he never forgot the one spell he knew: at a distance he throws an ember. Close the gap, or move.' },
 { t: 'bonecorsair', name: 'THE BONE CORSAIR', sub: 'the crew that never left', desc: 'A quick yellow cut, then a slower red cleave. Guard the first; move behind or away from the second. The bones rest after the heavy stroke.' },
 { t: 'tidemarauder', name: 'THE TIDE MARAUDER', sub: 'a scavenger of the drowned road', desc: 'The long harpoon can be guarded. The red low rake cannot: jump over its sweep, then close while he steps back.' },
  { t: 'sprig', name: 'SPRIG', sub: 'brush goblin', desc: 'Walks straight at you and bites. Sword it, stomp it, plunge it, or shove it back with the shield.' },
  { t: 'shield', name: 'SHIELDBEARER', sub: 'helmed goblin', desc: 'Blocks anything from the front with a clank. Turns slowly, so cross behind him and strike, or plunge from above. Stomps clank off the helm.' },
  { t: 'spit', name: 'SPITTER', sub: 'toadstool', desc: 'Spits a seed straight at your chest when you come near. Step aside, jump, block, or slash the seed out of the air.' },
  { t: 'pinemoth', name: 'PINE MOTH', sub: 'pale wings in the pines', desc: 'A big pale moth that hangs in the air over water and clearings. It does not go for you: stomp or plunge it to bounce, and chain the bounces across. One hangs high? Up+X: the rising cut.' },
  { t: 'wasp', name: 'WASP', sub: 'over water', desc: 'A stepping stone with wings. Stomp or plunge it to bounce, and chain the bounces across a pit.' },
  { t: 'thorn', name: 'SPIKE GOBLIN', sub: 'spiked iron back', desc: 'Winds up with a ! and charges. Block the charge to stagger him, or dodge through and hit him while he rests. The spikes on his back and helm punish stomps: sword only.' },
  { t: 'hopper', name: 'HOPPER', sub: 'marsh frog', desc: 'Leaps at you and leaps aboard rafts. Green is the common kind. Yellow hops quick and low. Blue is slow, heavy, and bites hard. Swing when it lands, stomp it, or block the leap.' },
  { t: 'archer', name: 'GOBLIN ARCHER', sub: 'keeps its distance', desc: 'Backs away and looses arcing arrows after a draw. Block them, or slash one to send it straight back and kill the archer. It will not cross water.' },
  { t: 'sapper', name: 'SAPPER', sub: 'goblin with a bomb', desc: 'Runs at you and drops a lit bomb at your feet. Block him and he drops it on himself. Dodge through and the bomb lands where you were.' },
  { t: 'turtle', name: 'SNAPPING TURTLE', sub: 'the river', desc: 'Slow, and its shell turns anything from the front: hit it there and it pulls its head in. It snaps on a tell; after the snap its neck is out and it is yours.' },
  { t: 'eel', name: 'EEL', sub: 'the plunge pools', desc: 'It only wants you in the water. Its eyes show before it lunges: be at the surface, or be out.' },
  { t: 'heronfoe', name: 'GREY HERON', sub: 'the shallows', desc: 'It stands so still you forget it. When its neck coils back, it is about to spear you. One cut and it is done.' },
  { t: 'crab', name: 'SHORE CRAB', sub: 'too far from the sea', desc: 'Claws up, it turns a blade. Come down on it from above and it goes over on its back, and then it is soft.' },
  { t: 'scout', name: 'TIDEBOUND SCOUT', sub: 'the watchers', desc: 'Pale and silent. It throws a harpoon at where you stand, twice, and then it is somewhere else. A parried harpoon goes back.' },
  { t: 'siren', name: 'SIREN', sub: 'the rocks', desc: 'She sings, and you walk toward her whether you mean to or not. Hit her and she goes under for a while.' },
  { t: 'tideguard', name: 'TIDEGUARD', sub: 'the drowned realm', desc: 'Coral plate turns half of a cut. The trident reaches further than you think: when it is drawn back, get out of its line, or block it and he is open.' },
  { t: 'cutlass', name: 'DECKHAND', sub: 'of the flotilla', desc: 'Quick, and the cutlass comes round in a wide swing that the shield holds easily. He guards while you wind up, so hit him on the end of his own swing. Two of them at once is the problem, not one.' },
  { t: 'boarder', name: 'BOARDER', sub: 'grapple and rope', desc: 'Throws a grapple from across a gap and hauls you in off your feet, which on these ships means into the water or into his mates. Break the line by putting something solid between you, or kill him while he hauls: he cannot let go and fight.' },
  { t: 'marine', name: 'MARINE', sub: 'in the tops', desc: 'Lives in the rigging and shoots down the length of a deck. He has to stand up to aim, and that is the moment to be somewhere else. Climb to him: he is nothing up close. His shot skips once off the deck, so the plank under you is not cover.' },
  { t: 'bosun', name: 'BOSUN', sub: 'he calls the watch', desc: 'Hits like a door with a belaying pin, and if he sees you before you are on him he puts the whistle to his mouth and the whole town knows. Close the distance or lose the level. The Salvage Captain also aims a grapnel, drops marked cargo and fires low quay guns: block the pin and hook, leave the cargo marks, jump the shots. Half wounded, both guns fire and three cargo lanes drop. Strike during his recovery.' },
  { t: 'lookout', name: 'LOOKOUT', sub: 'eyes, and a whistle', desc: 'Cannot fight at all. All he does is see you, and then fill his lungs. He needs a breath and a bit to do it: that is how long you have.' },
  { t: 'watch', name: 'THE DROWNED WATCH', sub: "a constable on his beat", desc: 'Still walking a beat in a city that drowned a hundred years ago. He guards with the haft of the halberd, so a light blow turns on it and only a HEAVY one gets through. He cannot see you under a burning lamp, and out of the light he hears you from twice as far and comes faster. His thrust has the longest reach of any foot soldier: step in or step out, never back. Crowd him and he takes your feet with the butt of the spear.' },
  { t: 'lampreeve', name: 'THE LAMPREEVE', sub: 'he goes the other way now', desc: 'He lit this street for forty years and has been putting it out ever since. He walks to the nearest burning lamp and hoods it. CARRY FIRE TO A LAMP HE PUT OUT AND RELIGHT IT BESIDE HIM: the flare stuns him, open. Strike the lamp under his hood and it flares in his face, a shorter opening; otherwise his wet coat takes most of a blow. Jump the low sweep; step off the shadow of the oil flask - its slick sends a relit flare wide; a line beats the hook. Out of the light he lunges, red. At half health he takes YOUR light: relight it at a lamp.' },
  { t: 'tollmaster', name: 'THE TOLLMASTER', sub: 'the magistrate of a drowned city', desc: 'He never stopped collecting. THE TOLL IS YOUR LIGHT: he COLLECTS the lamps of the square - stand in the stream or strike his box and the lamp keeps its flame. Carry fire from his braziers and RELIGHT a lamp beside him: his robes catch, and he is stunned and open. PARRY the chained ledger and the book turns. Jump the rod and the low swing of the scales; duck the high one. Carried, three blows on one corner fell its bearer and the bier tilts. On his feet he stamps a SEAL OF DEBT under you: step off its shadow, and off the wax. Last of all he fills the square: the lamps are the only air, and a WRIT OF DROWNING floods the hoods on your half.' },
  { t: 'captain', name: 'THE CAPTAIN', sub: 'he has not left her', desc: 'He tells you every one: two cuts of the sabre, a brace of pistols, a grapnel that hauls you in unless you hold a line, a lit keg down her planking - and he calls the sea. His front is a wall: go round or over. When the sea comes he makes for a line: take it from him and the wave knocks him flat. In his fight the sky marks the deck between you: let him walk into it.' },
  /* THE HEXED FIELDS */
  { t: 'scarecrow', name: 'SCARECROW', sub: 'the hexed fields', desc: 'It only moves while your back is to it: a twitch, then a lurch nearer. Face it and it stands like straw. Close in, it swings its sickle on a yellow mark.' },
  { t: 'rook', name: 'FIELD ROOK', sub: 'the hexed fields', desc: 'Perched on the fences until you come near. It circles, marks a spot on the ground under you, and dives at it. One blow brings it down, and it makes a fine step.' },
  { t: 'farmhand', name: 'GHOST FARMHAND', sub: 'the hexed fields', desc: 'A labourer who never went home. He drifts through walls behind his lantern and brings his hoe down on a slow yellow mark. Walls do not stop him.' },
  { t: 'pumpkin', name: 'PUMPKIN LURKER', sub: 'the hexed fields', desc: 'A pumpkin like any other until a puff of spores comes out of it: a red mark, and it bursts up at you from below. Step back from the puff. On its legs it bites.' },
  { t: 'marshlight', name: 'MARSHLIGHT', sub: 'the hexed fields', desc: 'It drifts out over the bog ahead of you, and flares if you get too close. Strike it and its light holds the phantom planks under it, cloud or no cloud.' },
  { t: 'haunt', name: 'POLTERGEIST FORK', sub: 'the hexed fields', desc: 'A pitchfork nobody is holding. It shakes on a yellow mark and throws itself at you. Take it on the shield and it drops to the floor, stunned.' },
  { t: 'boo', name: 'THE SHY DEAD', sub: 'the hexed fields', desc: 'It only drifts while your back is turned, and it hurts to touch. Face it and it stops dead, both hands over its eyes: harmless, and it will not move again until you look away.' },
  { t: 'ploughman', name: 'THE HEADLESS PLOUGHMAN', sub: 'the furrows', desc: 'On the red mark he drives his plough the length of the field: jump it. It sticks only in the trough or the fence: stand so one is in its path, and cut him while he heaves. His burning head comes down on the red ring: be off it. Up close, the goad. At half health his furrows wake: when they glow, get off them.' },
  { t: 'strawking', name: 'THE SCARECROW KING', sub: 'the burning cornfield', desc: 'Straw takes a blow and stands. On his pole: cut the pole. Built bigger: strike a trough by its vine and it holds him. Burning: knock his lantern into his straw with a heavy blow, a dash or a plunge.' },
  /* THE MAGE'S FOLLY */
  { t: 'topiary', name: 'TOPIARY BEAST', sub: "the mage's folly", desc: 'A hedge cut like a hound, until you are near. It shivers all over first, then it hops at you and swipes on a yellow mark. Leave it and it roots itself again.' },
  { t: 'armour', name: 'ANIMATED ARMOUR', sub: "the mage's folly", desc: 'Plate with nobody in it. It walks slowly and holds its sword up for a long yellow beat before it comes down. Broken, it comes apart into gauntlets that crawl.' },
  { t: 'piece', name: 'A CRAWLING PIECE', sub: "the mage's folly", desc: 'A gauntlet that gets up after the armour is down and comes for your ankles. One blow settles it.' },
  { t: 'broom', name: 'BROOM AND BUCKET', sub: "the mage's folly", desc: 'The mop that never stopped. It bobs round you, tips back on a yellow mark and rams; a shield turns it and knocks it silly. Weak, but they come in swarms.' },
  { t: 'mimic', name: 'MIMIC CHEST', sub: "the mage's folly", desc: 'A chest until you reach for it. Then teeth, a snap on a yellow mark, and it hops after you. Step back from the mark and cut it while it chews air.' },
  { t: 'tome', name: 'THE TOME', sub: 'the falling tower', desc: 'A book that was read too often. It drifts by its shelf, riffling; inside seven tiles it flings its covers wide on a yellow ! and darts at the spot you were standing on. It does not steer, so a step under a steep one or a jump over a flat one answers it - and so does the shield, which SLAMS IT SHUT: down it goes, and every blow counts twice while it lies there. It hurts only mid-dart.' },
  { t: 'imp', name: 'IMP', sub: "the mage's folly", desc: 'Out of its jar and pleased about it. It hovers off the floor, throws fire on a yellow mark, and hunches into a puff of smoke before it hops somewhere else.' },
  { t: 'turret', name: 'ARCANE TURRET', sub: "the mage's folly", desc: 'A brass eye he left switched on. It brightens for a long beat and spits a slow orb at where you were. Outrun it, or take it on the shield.' },
  { t: 'homunculus', name: 'THE HOMUNCULUS', sub: 'the library cell', desc: 'Grown in a jar and still wearing it. A red SCUTTLE under you (jump it), a yellow POUNCE and SWIPE (the shield turns them), a red POUND along the floor (jump it), a red FLASK onto the ring (move). A trick that MISSES you costs it the jar, smashed where you stood: bare, cut it. At half health its tricks come in pairs, and it hides in the smoke of its broken jar.' },
  { t: 'archmage', name: 'THE ARCHMAGE', sub: 'the top of the tower', desc: 'He blinks round his room every few seconds - a flash shows where he will stand. He draws circles under you (yellow the shield turns, red you leave), and he wards: three runes stand round the room, and they seal again if you are slow. At each ward a portal opens and one of his dead apprentices steps out. Then he rewrites the room three times; each room turns on you, and gives a way to him. Last, the room is put right and he is three: two images cast with him, but only his own spells are coloured. Strike an image and it breaks.' },
  { t: 'kraken', name: 'THE KRAKEN', sub: 'the sea come to collect', desc: 'For a hundred years the goblins paid the deep a tribute to keep it asleep. The tribute stopped; this is what came up the Long Water to collect it. FIRST, ITS ARMS: they come up along the road and work together - one slams while another sweeps. The slam sends a ring out along the stones (jump it or shield it); ink lands in dark patches that hide an arm and slow you; spouts mark the stones before they go; a red !! is THE WAVE - get behind a crate or up high, or jump its crest. Cut the arms where they lie. THEN THE CARGO: the tide lays crates on the road - break one while he is up and it hits him. When he must BREATHE a bubble and a timer stand over him: strike a glinting bell and its ring runs out to him - knelled, his arms fall limp. LAST, THE CLIMB: he hauls himself up against the end of the road. Cut through an arm he slams and it falls as a ramp to his head; climb it, jump when he shakes it, and strike the great EYE while its gold ring is open. Behind a waystone, his spear arm still sticks fast.' },
  { t: 'feeler', name: 'FEELER', sub: 'an arm in the flats', desc: 'The mud stirs, and then there is an arm in it. It rears back over its root and lashes along the ground: the shield turns it, and a turned lash lies out on the stone to be cut. Hidden, it cannot be struck.' },
  { t: 'masthead', name: 'THE MASTHEAD', sub: 'the wind is his floor', desc: 'The biggest sail goblin. His gaff swing the shield turns. He fills his sail and rams you down the deck: block him, let him hit the rail, or turn the wind on him at the winch, and he fouls in his canvas. He drops out of the rigging and lets the boom go at your knees: nothing turns either.' },
    { t: 'champion', name: "THE ADMIRAL'S CHAMPION", sub: 'the fleet\'s last word', desc: 'A huge salt-crusted knight in plate, the fleet\'s champion, with a two-handed boarding greatsword. His plate turns most of a blade. Every swing is committed: cut him in the recovery after it. Step out of his overhead and the blade sticks in the deck. He leaps the lashing to whichever hull you stand on. Strike a deck gun while he stands in its line and the round shot knocks him flat. At half he tears the anchor off the rail: it sweeps round him at your knees, it hooks and hauls you, and its slam tilts the deck toward the lashing.' },
  { t: 'sailor', name: 'DROWNED SAILOR', sub: 'still working the wreck', desc: 'Slow and heavy, and the boathook reaches a long way low. Jump the sweep or take it on the shield: a parried hook leaves him wide open. He guards while you swing, so hit him after his own swing, not before.' },
  { t: 'netter', name: 'NETTER', sub: 'the drowned fisher', desc: 'Keeps its distance and throws a weighted net that holds you where it lands. Mash anything to tear out. It has only the one net: rush it while it is empty-handed.' },
  { t: 'merrowspear', name: 'THE SPEARFISHER', sub: 'the sea has its own goblins', desc: 'Throws a harpoon on a line. Raise a shield and the head turns; roll through the line before it lands and it parts. Caught, it hauls you toward her, so keep your feet under you or you go where she wants.' },
  { t: 'merrowcaller', name: 'THE TIDECALLER', sub: 'the tribe’s shaman', desc: 'Holds a long channel and the water takes you, shoving you along whatever floor she stands over - into a hazard, or off an edge. Land a hit on her while she holds it, or stagger her, and it breaks and leaves her stunned.' },
  { t: 'merrowbrute', name: 'THE MERROW BRUTE', sub: 'a clam shell for a shield', desc: 'Turns anything from the front and rams when you crowd it square-on. Cross behind it and strike, break its poise, or plunge from above and crack the shell. Too heavy to throw.' },
  { t: 'drownedknight', name: 'THE DROWNED KNIGHT', sub: 'the drowned court, still at arms', desc: 'He swims after you, slower than you, and it is the lunge that closes the gap: the blade drawn back, bubbles along its line, then a drive at where you WERE. Guard it and he is thrown back open. Three good cuts put him down.' },
  { t: 'whelp', name: 'GARGOYLE WHELP', sub: 'the gate gargoyle\'s brood', desc: 'Stone, and nothing you swing or shoot does more than spark off it. When it has seen you it crouches and SCREECHES, then dives at you and on down: take it and it shoves you off your feet, guard it and it clangs away. Let it dive through a cracked ledge into the spikes and it sticks there, stunned. Jump on it then - nothing else breaks it - and the wind of the moat lifts you back up. Out of its reach it spits one small fireball instead; a shield takes it.' },
  { t: 'drownedcaptain', name: 'THE DROWNED CAPTAIN', sub: 'he holds the door for his king', desc: 'The knights\' captain: a red plume in the water, a heavier blade. The lunge, and the blade raised over his crest for a CUT and a RETURN CUT - guard both, or be gone before the second. Kill him and his gate lifts.' },
  { t: 'urchin', name: 'URCHIN', sub: 'spines in the water', desc: 'Drifts, then follows you when you swim near. Its needles stand up as you close in: only a risen urchin stings. Go round, or kill it from a distance.' },
  { t: 'angler', name: 'ANGLER', sub: 'the light in the dark', desc: 'Hangs in the deep with its lure lit, and bites the length of its own body when you come close. The lure flares first: that is the tell. Everything it does is in a straight line, so be somewhere off it.' },
  { t: 'petrel', name: 'STORM PETREL', sub: 'off the wrecks', desc: 'Circles above and dives on a line at where you are, not where you will be. Walk out of the line, or take it out of the air.' },
  { t: 'puffer', name: 'PUFFERFISH', sub: 'small until it is not', desc: 'Drifts, harmless, until you come close: then it swells on a yellow mark and bursts a ring of spikes the shield can still hold. Hit it while it is flat and it goes flying, into whatever else is in the water.' },
  { t: 'jelly', name: 'JELLYFISH', sub: 'a clock in the water', desc: 'Rises and sinks on its own slow cycle and fans its tentacles at the bright end of it: that is when it stings. It never chases and it never hides its clock: read the glow.' },
  { t: 'lamprey', name: 'LAMPREY', sub: 'the breath thief', desc: 'Closes fast and latches on, and every second it holds you it takes a bite of your air, not your blood. It lets go on its own, but a dodge shakes it off at once.' },
  { t: 'manta', name: 'MANTA', sub: 'off the open water', desc: 'Skims the sea beside the deck and dives at whoever is standing on it. Her shadow runs ahead of her on the boards: watch the boards, not the sky.' },
  { t: 'reefmaw', name: 'THE REEFMAW', sub: 'a moray the length of a mast', desc: 'It has four holes and is only in one: bubbles say which. Its hide turns a blade while it lurks. When its bite hits coral instead of you, its jaw sticks fast: cut it then. The hole floods; then the tide goes out and it hauls itself onto the reef. Jump its lunge and it beaches itself, belly-up.' },
  { t: 'herald', name: 'THE TIDE HERALD', sub: 'he comes up with the sea', desc: 'An old knight of the drowned realm who walks on the water. His plate turns most of a blade. When he raises the glaive the sea comes across the square: get up on the stones. Then the tide goes out and leaves him in the mud, and the mud is where he bleeds.' },
  { t: 'soldier', name: 'SOLDIER', sub: "the queen's line", desc: 'Sword and shield, and he knows how to use them. The shield turns anything from the front and he is slow to turn: get behind him, or cut him as he swings. Hold the shield and it only turns his cut; raise it as it lands and he is wide open.' },
  { t: 'javelin', name: 'JAVELINEER', sub: 'the skirmish line', desc: 'Keeps his distance and throws at where you stand. Parry a javelin and it goes back at him. Close in and he runs. A throw that finds a wall stands in it for a while, and a spear in a wall is a step.' },
  { t: 'heavy', name: 'HEAVY KNIGHT', sub: 'full plate', desc: 'Slow, and his plate turns most of a cut. A double mark is the overhead: get out from under it. A single mark is the sweep: a shield already up only turns it - he does not flinch - but raise it as it lands and he is rocked off balance. He is open while he drags his blade out of the floor, and a plunge finds the gaps in his helm. Hide behind your shield in front of him and he takes hold of it - a double mark, and the shield is no answer.' },
  { t: 'brute', name: 'BRUTE', sub: 'club goblin', desc: 'Two tells. A double mark is the overhead: it cannot be blocked, so dodge it. A single mark is the sweep, which the shield holds. Hit him while the club is raised or while he rests.' },
  { t: 'hound', name: 'WAR HOUND', sub: 'goblin dog', desc: 'Runs straight at you and leaps low at the last stride. Stomp it, swing as it lands, or put fire between you.' },
  { t: 'grub', name: 'CAVE GRUB', sub: 'it glows because it burns', desc: 'A soft thing lit from inside. Near you it beads and flares, and a flared grub burns on touch: cut it, or keep out of the arc of acid it spits when you stand off. It leaves its light behind for a moment when it dies.' },
  { t: 'rockgoblin', name: 'ROCK GOBLIN', sub: 'thrower in the dark', desc: 'Squat, patient, and armed with whatever the roof has dropped. It lobs a lit lantern that breaks into fire and light where it lands, which is a problem and a favour at once. Close the distance and it has nothing.' },
  { t: 'shardling', name: 'SHARDLING', sub: 'a knot of crystal that walks', desc: 'Easy to kill and a poor idea to kill from close. It bursts when it goes, and the burst does not care whose side anyone is on: put one next to a rock goblin and let it do the work.' },
  { t: 'fledgling', name: 'ROC FLEDGLING', sub: 'too big for the nest', desc: 'Turned out of the nest when it grew too big for it, and gone down the mountain into the ruins. It cannot fly yet. It waddles at you and rears back before it pecks, and a shield turns the beak.' },
  { t: 'winchmaster', name: 'THE WINCHMASTER', sub: 'the drum house on the ore road', desc: "He works three drum houses on the ore road, and every one has a ladder up to him. Up there he brings THE BRAKE BAR round (the one blow a shield turns) and throws THE HOOK to drag you off the edge; down the lines he SENDS loaded buckets and REVERSES the drum on a rider. He packs ORE ARMOUR round himself, and a blade on it only chips: take a ROCK off one of his loaded skips and THROW it, and the ore shatters - he is knocked down onto his ledge, STAGGERED, for double. He tosses ore at you, tips skips over you, and sweeps the chain low. Take a quarter of his strength and he retreats along the cable to the next housing, and packs his ore again. Ride a loaded bucket into his drum and it jams: he goes down on his ledge for double." },
  { t: 'abbot', name: 'THE FALSE ABBOT', sub: "in the abbot's chair", desc: "The priest's superior, in a cope that fits and a mitre that does not. He blesses himself as well as his congregation, and a warded Abbot takes a FIFTH of every blow - so the sword is not the answer. THE GREAT BELL IS: ring it while he stands under it and the note goes through the rite, breaks every blessing on the roof, and puts him down. Getting him under it is the fight - guard his chain and it hauls him toward you; stand past the bell and he swings to you on the belfry ropes, landing under it. When he kneels to pray, strike the sanctus bell behind him or come down on him: the rite is spoiled." },
  { t: 'gobpriest', name: 'GOBLIN PRIEST', sub: "in the monks' robe", desc: 'Its rite mends the goblins near it and blesses them: half of every blow. Any blow breaks the rite. Far off it lobs its censer at you, close in it rings you back with its bell. Kill it first.' },
  { t: 'gobmage', name: 'GOBLIN MAGE', sub: 'it found the library', desc: 'It keeps its distance. Its bolt is slow: strike it or take it on a shield and it goes back. When it lifts the book it is writing a rune under your feet, and no shield turns that. Move.' },
  { t: 'sentry', name: 'CASTLE SENTRY', sub: 'the Queen\'s watch', desc: 'A goblin in a kettle helm whose whole job is a bell. See him before he sees you: once he has you he runs for it, and a rung bell drops the gates of that hall and turns out the garrison. Catch him on the way, or break the bell.' },
  { t: 'gqueen', name: 'THE GOBLIN QUEEN', sub: 'the last of the goblin line', desc: 'Old, huge and clever, and she does not charge: she holds court. She leaps about her hall and lands in a quake that runs the floor - jump it. When she lands beside one of her cracked pillars she turns her back and points, and her gallery looses where she points: break that pillar, three blows, and it comes down on her. In her second round the pillars stay down and her plate wears its own bar - drop a chandelier on her, or strike her back while she points, and when it breaks she is fought like any foe, and fights like a duelist. At the last her crown burns.' },
  { t: 'suncatcher', name: 'THE RIMEWRIGHT', sub: 'it works the ice', desc: 'Frost down the floor: jump it. Spires under you: move. Cold light and claws: block. The rime turns part of every blade. Burn the rime off it at a firebox, or break its own spire on it.' },
  { t: 'roc', name: 'THE ROC', sub: 'mother of harpies', desc: 'She drove the monks off their mountain and nests on their roof. In the air she is quick and hard to hurt. She comes down for two reasons: to take you, and because something knocked her down. A shadow marks where she will dive, and if she dives onto the old roof boards her talons go through and she is stuck. She beats her wings to throw you on the thorns, and hurt, she sheds. A brazier throws its coals up when it breathes, and the nest bell goes through her if she is over it.' },
  { t: 'grandmother', name: 'THE GRANDMOTHER', sub: 'she never was asleep', desc: 'The oldest goblin in Underleaf, and she has not seen anything for forty years. She does not follow you, she follows the last sound you made, and she hears a blade coming: from the front her stick turns it. Her BACK is the way in. Break a pot behind her, or pull a bell-pull and let its chime ring across the room, and she whirls to the sound and lashes at it - and stands there with her back to you. When she stands and listens, make no sound at all and she raps the floor in temper.' },
  { t: 'bellman', name: 'THE BELLMAN', sub: 'the night-watch of underleaf', desc: 'Blind, and the best ears in the village: an ear trumpet and a handbell. He walks his beat and turns to any sound, and goes to see. Make a sound of your own inside his ear and he rings - the street wakes and its gate comes down. A pot thrown past him sends him to look at the wrong place. From behind, one blow and he never rings at all.' },
  { t: 'assassin', name: 'GOBLIN ASSASSIN', sub: 'the one who is awake', desc: 'He carries no light, which is how you know him: everything else in Underleaf has a candle. He waits without moving and you will not see him. What you WILL get is a whisper and a ring where it came from - that is the only warning, and what follows it goes straight through you and cannot be blocked. He comes up behind and thrusts, and THAT one the shield turns: parry it and he is yours.' },
  { t: 'berserker', name: 'GOBLIN BERSERKER', sub: 'no guard, no stopping', desc: 'They shut him in for the night, and everyone within half a mile knows when he is let out. He has no shield, no guard and no patience: he runs in a straight line and he cannot turn while he does it, so go through him and hit his back. A swing that finds nothing puts him on his face. So does a wall. Half dead he stops falling over, and then it is just the two of you. The one they chain at the Waymeet swings that chain: stand off and it hauls you onto his run.' },
  { t: 'gravewarden', name: 'THE GRAVEYARD KEEPER', sub: 'the ossuary keeps its keeper', desc: 'Huge and slow, a spade and a bell-lantern on a chain. Guard his spade and his grave dirt; jump the lantern when he whirls it low; move when the earth cracks under you, because a dead hand comes up there. His dig follows you: stand beside an open grave and leave late, and the spade goes into the grave and puts him on his knees, open. When he tolls, the dead climb out of the graves - and past half, every toll seals one for good.' },
  { t: 'gargoyle', name: 'THE GATE GARGOYLE', sub: 'bolted over the tower gate', desc: "Stone, and woken by the loose magic: no blade, spell or shot takes anything off him. He rises out of sight and comes down on the slab his shadow finds - be on another one when he lands. His fire runs out along a line you can see set, and he spits two slow fireballs, one after the other; a shield takes all of it. Leave his slab late and he smashes through it onto the spikes, stunned. Jump on him there. The wind lifts you back up, and the slab grows back." },
  { t: 'sexton', name: 'THE SEXTON', sub: 'the falling tower keeps its bell-ringer', desc: 'He rings the loft on its failing deck. Guard his swing and his charge; when the bell goes up, get off the planks - the toll strikes the deck and sets it counting. Charge him across a counting plank and he goes through, caught and open.' },
  { t: 'hedgewarden', name: 'THE HEDGE WARDEN', sub: 'the garden keeps its gate', desc: 'A topiary knight as tall as the garden wall. Guard his cut and his charge; when he flings his arms wide the thorns come out all round him, and no shield turns them - get clear. His thorn lash cracks along the lawn well out in front of him: guard it or jump it. When he drives his sword into the lawn, roots crawl out at you: jump them, or stand at a brazier, where the witch-fire burns them out. Cut him down and he falls to a stump that stands him up again, and a stump on the open lawn is green wood a blow only chips. He follows you. Fell him beside a witchlight brazier and the fire takes the stump - it cannot grow while it burns, and every blow counts twice.' },
  { t: 'burngob', name: 'BURNING GOBLIN', sub: 'it carries the fire', desc: 'A goblin already alight. It fights like the others - a told swing a shield turns - and touching it costs nothing. What it costs is the ground: the straw it walks on catches, and so does the straw it dies on. Kill it on bare ground.' },
  { t: 'emberwisp', name: 'EMBER WISP', sub: 'the fire that drifts', desc: 'Its touch is its blow, and nothing turns it: the red cross is over it whenever it is near. It is slow and it turns wide, so it cannot double back on you, and it will not pin you to a wall. One cut puts it out.' },
  { t: 'pyromancer', name: 'THE PYROMANCER', sub: 'a renegade of the order', desc: 'He fights with the Pyromancer\'s own staff - her run of three cuts and her held blow, THE BELLOWS, that no shield turns - and her ember, and he hops the stalls to meet you. He reads a run: the third light blow in a row he turns, but a heavy goes through. Struck while he runs hot he OVERHEATS, open. A thrown bucket of water puts him out and opens him too. The square burns with his bar.' },
  { t: 'scalder', name: 'THE SCALDER', sub: 'he holds the top of the ladder', desc: 'A goblin and a pot of boiling pitch on the lip of a tower. Climb under him and he tips it straight down the ladder: no shield turns it. Wait on a landing while he stirs the pot back up, then climb.' },
  { t: 'temperer', name: 'THE TEMPERER', sub: 'he goes back to the fire', desc: 'The least dangerous thing in the hall until he turns and runs. He fetches the heat himself: at a lit brazier the blade comes back glowing, and the next blow is one no shield turns. Catch him at the fire, or put the fire out.' },
  { t: 'hearthgob', name: 'HEARTH GOBLIN', sub: 'it lives here', desc: 'Asleep by its own fire until you are close enough to wake it, and then it comes at you with a stool. Not a soldier. Worse than it sounds in a room you cannot back out of.' },
  { t: 'sweep', name: 'CHIMNEY SWEEP', sub: 'up the flue', desc: 'He lives in the stacks. Walk past and he comes up out of one with a handful of soot, throws it, and stays up a moment to watch it land: that moment is the only time you can reach him. Then he is back down the flue.' },
  { t: 'stormshaman', name: 'STORM SHAMAN', sub: 'the weather is his', desc: 'A goblin with a staff who stands at the far end of a span and throws the storm at whoever is crossing it. His bolts are slow: strike one, or take it on a shield, and it goes back at him.' },
  { t: 'seawitch', name: 'THE SEA WITCH', sub: 'she signed the articles too', desc: "The ship's conjuror, in the crew's own coat, with a storm lantern on her crook. She marks a spot on the deck and the sky finds it a second later: no shield turns lightning, so move. Out of the weather she throws it by hand instead, slow enough to strike out of the air or send back off a shield." },
  { t: 'lance', name: "THE QUEEN'S LANCE", sub: 'he holds the bridge', desc: 'A goblin knight in plate the size of a door: it turns a blade from the front, not from behind or above, and committed he is open. He cannot steer a charge: step off his line and the lance goes into a post and he goes with it, and that is when he bleeds. Or MAKE the opening: a DASH ATTACK into his guard takes his feet out and he reels - it draws no blood itself, and he sets his feet against the next one for a while. Not while he is coming at you. His thrust can be parried; the low sweep cannot, so jump it. When a horn goes on a tower, one of HER bowmen is coming down onto an end lookout: he is only an archer, so cut him down. Half dead he throws the lance away, takes a shield, and becomes the opposite problem.' },
  { t: 'snuffer', name: 'THE SNUFFER', sub: 'lamp-killer', desc: 'It is not hunting you. It walks the boughs putting the village out, one lantern at a time, and the Reeve is glad of it. It swings the pole if you crowd it. Light what it snuffs, or cut it and the lamps stay lit.' },
  { t: 'sailer', name: 'SAIL GOBLIN', sub: 'carried, not driven', desc: 'A plank of sail and no way to steer. In the lull she shuffles at you and is nothing. When the gust takes her she is a battering ram: block her and she spills, or step aside and let the stone take her. THE MASTHEAD is the biggest of them.' },
  { t: 'horn', name: 'HORNBLOWER', sub: 'a gale of his own', desc: 'A goblin on a mound with a ram\'s horn. He winds it at you and a horn\'s worth of wind comes with it: on the ground it slides you back, in the air it throws you. Get under it or get to him; one good cut and he stops blowing.' },
  { t: 'crow', name: 'STORM CROW', sub: 'they do not turn', desc: 'They come down the wind over the high moor in strings of four and five, and a string does not turn for anyone. On the Sky Road there is no ground to stand and cut them from: go over, go under, or go through with a dart.' },
  { t: 'oldtusker', name: 'OLD TUSKER', sub: 'the great boar of the felling clearing', desc: 'The oldest boar in the wood, grey at the muzzle and scarred to the bone. His hide turns a cut: come down on his back, or use the clearing. He paws and snorts before he charges, and the charge runs past the standing pines to the wall. Four strokes fell a marked pine, and it falls the way it leans: lay three in early and strike the fourth when he is under it - pinned, he takes it all. A pine that misses him lies across the floor: his charge rams the trunk and he reels, and the trunk splinters. Jump his tusk sweep or parry it; step off the red rings of the clods he roots up. At half his blood is up: a charge that misses turns and comes straight back, and he rears to stomp a shockwave along the ground - jump it.' },
  { t: 'queen', name: 'HORNET QUEEN', sub: 'hive ruler', desc: 'Hovers out of reach and calls drones. While TWO are up the swarm closes over her and turns most of a blow. Her dive pulls up off bare earth, but lure it onto wood and leave late: her sting sticks, and she is open. Block the dive and she staggers. At half health she hangs in her comb and comes down only to sting.' },
  { t: 'frog', name: 'BULLFROG KING', sub: 'lord of the marsh', desc: 'Sits on a royal pad out in his biting court, and there he is never armoured: cross the pads to him and cut. Hurt him enough and he leaps to another pad, and the leaves reshuffle. Shield or jump his tongue, lead his flies onto his head, jump his belly-flop wave. At half his pond stirs.' },
  { t: 'sporeling', name: 'SPORELING', sub: 'walking cap', desc: 'Wanders and bites. Kill it and it bursts into a spore cloud that slows and tires you, so finish it at range or step back.' },
  { t: 'spitcap', name: 'SPITCAP', sub: 'rooted lobber', desc: 'Rooted, so it lobs. The bomb is nothing: the sleeping cloud it leaves is everything. It swells before it throws, and while it is swollen it comes apart in one blow.' },
  { t: 'weaver', name: 'WEAVER', sub: 'pale spider', desc: 'Hangs in its curtain and spits web that holds your feet. Mash out of the web, and cut the curtains: they are what it hides behind.' },
  { t: 'lurker', name: 'LURKER', sub: 'hungry mushroom', desc: 'Looks like scenery until you pass, then lunges. Walk, do not run, through mushroom groves, and swing at caps that look too plump.' },
  { t: 'drone', name: 'SPORE DRONE', sub: 'floating puffball', desc: 'Drifts toward you and bursts. Swords bounce off it. Stomp it out of the air or plunge it.' },
  { t: 'shaman', name: 'TOAD SHAMAN', sub: 'walking toadstool', desc: 'Raises sporelings from the ground and vanishes in a puff when struck. Chase it down first.' },
  { t: 'thief', name: 'GOBLIN THIEF', sub: 'cutpurse', desc: 'Stalks you and snatches gold from your pockets on touch, then runs. Catch him and it comes back with interest. Runs from a thrown shield too slowly.' },
  { t: 'pike', name: 'PIKEMAN', sub: 'holds the line', desc: 'A long pike that turns your blade from the front. Jump over him, get behind, or throw the shield. Block the thrust to parry it.' },
  { t: 'folk', name: 'TOWNSFOLK', sub: 'they live here', desc: 'Harmless. They run for their doors and slam them. The court cheers the King and hides when he stands. Hurting them is beneath you.' },
  { t: 'master', name: 'THE HOUND MASTER', sub: 'the goblin lord\'s huntsman', desc: 'On a war-hound that takes the cut for him. CHARGE: block it and the hound rears. LEAP: roll clear; it sprawls. LASH: parry it. CRACK: jump the whip. Purple over his head is the WHISTLE: dogs from the walls. Loose the kennel hound and it bites the mount.' },
  { t: 'greathound', name: 'THE GREAT HOUND', sub: 'the kennels\' own', desc: 'A hound the length of a cart. LUNGE: jump it, or block it and it skids past you, open. POUNCE: dodge sideways; it lands stunned. THE BOUGHS: it rears against the oak and dead wood comes down on the red rings - get clear. It is never untouchable: its jaws turn part of a blow struck into its face, so go round it or come down on it. HOWL: two pups come; kill both quickly and it whines, open for a long while. Past half its blood it snaps at anything beside it. The chained kennel hound, freed, bites it too.' },
  { t: 'spider', name: 'BOUGH SPIDER', sub: 'thread and fang', desc: 'Hangs from the bough above on a thread. Walk under it and it drops, bites, and yanks you sideways off the ledge. It climbs back up slowly: hit it then, or stomp it as it hangs. The big one, the Weaver, casts a line at you when you stand off and reels you in under the drop.' },
  { t: 'squirrel', name: 'SQUIRREL KNIGHT', sub: 'the tree-city\'s cutpurse', desc: 'A red squirrel in a tabard. Snatches your gold on touch and hops up the tree with it. Catch it before it climbs out of reach and the gold comes back with interest.' },
  { t: 'miner', name: 'GOBLIN MINER', sub: 'pick and candle', desc: 'Digs through soft rock toward you and leaves the tunnel behind for you to use. Swings a pick with a slow, heavy tell: block it and he is open. Across a gap he THROWS it - and then he has nothing at all until he walks over and picks it up again, and he will not take it out from under your feet. Drops his lamp when he dies, and the lamp stays lit.' },
  { t: 'tippler', name: 'THE TIPPLER', sub: 'he works the frame', desc: 'He minds a tipping frame and he never comes after you. He waits until something is UNDER him, heaves the bar - a red cross, and a second of it - and a skip of ore goes over the edge. No shield turns falling rock, so the answer is not to be there: brake the bucket short, or be past him before the bar comes up. Close in he has the bar itself, and that a shield does turn.' },
  { t: 'sheargob', name: 'THE SHEARGOB', sub: 'the long shears', desc: 'A lineman with cable shears taller than he is, and he reads the V over his head: carried shut, he is only walking. He LEAPS ONTO THE BUCKET YOU ARE RIDING and starts on its hanger, and when the shears close the skip goes into the gorge with you in it. The bucket is wide enough to fight him on - that is what it is wide for. Kill him, or get off.' },
  { t: 'gaffer', name: 'THE GAFFER', sub: 'eight feet of boat hook', desc: 'The longest reach of anything in the game, and he only uses it on something that is MOVING PAST him. Ride by and the hook takes you off the bucket and out over the drop, and no shield turns a hook. Stop short of him and he is an ordinary goblin with an awkward weapon: the brake is the answer to him, which is the whole lesson of the road.' },
  { t: 'bat', name: 'CAVE BAT', sub: 'hunter of lamps', desc: 'Hangs in the dark and cannot see you. It sees light: a lamp, a fire, an ember, the lamp you carry. Stand in the dark and it stays put; carry light through its roost and it comes. One hit kills it.' },
  { t: 'windcaller', name: 'THE WINDCALLER', sub: 'lord of the moor', desc: 'The goblin shaman of the moor. He stands on the high ledges of the summit and throws bolts of sky at you. The wind is the only stair up to him: the updrafts blow only in the gust, and the gust carries you onto his ledge. Send a bolt back at him up close and he falls. From anywhere, fire, a snatch, the aegis or a ward let go sends one home; when he rises he blows you home. Every so often he calls the wind itself, and it drags you toward the thorns.' },
  { t: 'kite', name: 'KITE GOBLIN', sub: 'hangs under a box kite', desc: 'Drifts on the gusts, edges over you and drops a stone. One cut, to the string or the goblin, and both come down: the goblin gets up as a sprig.' },
  { t: 'boar', name: 'BOAR', sub: 'the woodsmen\'s pest', desc: 'Roots about until you are close. On a yellow ! it paws, drops its head and charges along the ground, and it will not run off an edge. Jump it and come down on its back, or let it skid past and cut it while it shakes its head.' },
  { t: 'badger', name: 'BADGER', sub: 'the sett', desc: 'Roots about its scrape until you are close. On a yellow ! it digs in and charges along the ground, and it will not run off an edge. Jump it or shield it, and it skids and sits dazed: come down on its back.' },
  { t: 'gar', name: 'LONGNOSE GAR', sub: 'the deep holes', desc: 'Lies in dark water with only its snout showing. On a yellow ! it throws itself out onto the bank at you, and lies there flopping. Low on the ground it is the sweep\'s, or the plunge\'s.' },
  { t: 'hare', name: 'MOOR HARE', sub: 'runs with the wind', desc: 'Sits until you are close, then bolts with the wind, straight through you. Jump it.' },
  { t: 'wight', name: 'PEAT WIGHT', sub: 'stands up out of the bog', desc: 'Stand still in the bog and it rises beside you, cold hands out. It holds and drains. Keep moving and it never comes.' },
  // THE FACET's row went with the Glassworks. Its code is still here (spawn case, updateGolem, art) if it is ever re-homed.
  { t: 'prise', name: 'THE PRISE', sub: 'it wants what you are holding', desc: 'One claw the size of the rest of it and one that is no use at all. It has spent a hundred years prising things off the bottom and it does not much care that this one has hands: what it takes is your STONE, and down here that is worse than blood. Kill it before you pick anything up, or do not be carrying anything when it comes. The claw opening is the only warning there is.' },
  { t: 'holdfast', name: 'THE HOLDFAST', sub: 'rooted, and it does not let go', desc: 'Grown onto a wreck and it has never moved in its life. It does not chase and it does not aim - it waits, fronds open and drifting, and when it has you the water above you may as well be rock: you cannot rise, stone or no stone. Cut it off you. Fronds folded shut means it has already fed.' },
  { t: 'swornsword', name: 'SWORN SWORD', sub: 'waiting for work', desc: 'A man-at-arms off the road, and the first one in this game who fights the way you do. One cut, and he shows it to you for half a second before it comes. Hold the shield and he shoves you; raise it as the blow LANDS and he is wide open for a second and a half, and that is the only thing this town wants you to learn.' },
  { t: 'hedgeknight', name: 'HEDGE KNIGHT', sub: 'nobody owns him', desc: 'A great helm, a poleaxe and a surcoat that has been washed too many times. The swing round the side is a single mark and can be taken on the beat. The jump is a double mark and cannot be answered at all - it can only be left. Sometimes the first swing is a feint: guard on the second.' },
  { t: 'runner', name: 'THE RUNNER', sub: "somebody's squire", desc: 'Quick, unarmoured, and barely worth a swing. What he is for is the shout: once, he stops and fetches every sworn sword who can hear him, and they come at a trot. Reach him before he opens his mouth or deal with what he brings.' },
  { t: 'crossbow', name: 'CROSSBOWMAN', sub: 'up a stair', desc: 'He does not move and he will not come down. He winds, he levels, and the bolt goes where you were standing when he levelled it. The shield turns it - and sends it back up the stair - so he is the reason your guard is up when somebody walks in with a sword. A bolt goes through a shield held up early: only a guard raised as it lands turns it, and that one goes back up the stair.' },
  { t: 'closedhelm', name: 'THE CRUSADER', sub: 'sworn to the chapel', desc: 'His ward faces you: go round him or over him - or answer his SWORD. Every blow is told by his stance and a GLINT on the blade: guard, parry or roll AT the glint and the ward breaks; too early and he cuts straight back through your shield. One overhead is held long - wait for the glint. His GRAB is red: roll through it. THE BASH runs a red line: roll it or be gone. JUDGEMENT marks your feet: step off. Enraged, the low OATH (jump) and RADIANCE (a gap); near the end HOLY BRAND runs fire along the floor: jump it.' },
  { t: 'drunk', name: 'THE DRUNK', sub: 'a regular, gone rowdy', desc: 'He has been at the Broken Lance since noon and he has found a balcony. He throws what is to hand - a tankard, a turnip, a stool - and a yellow mark means the shield turns it. A red mark is a bottle: it cannot be blocked and it leaves glass. Watch the ring on the ground. One blow puts him on his back.' },
  { t: 'lancer', name: 'SERJEANT', sub: 'mounted, on the bridge', desc: 'A man-at-arms on a barded horse, riding his beat end to end. The charge is a single mark: take it on the shield and he goes over the back of his horse, or jump or roll it. Close to him he swipes with his sword. Mounted, the barding takes some of every cut; in the road he is a man with a sword and no horse.' },
  { t: 'undeadmage', name: 'THE UNDEAD ARCHMAGE',sub:'the last spell outlives him',desc:'Fought from the carpet in his burning hall. His ward turns every blade: STRIKE HIS SPELLS BACK AT HIM - every bolt, lance, orb and hand of his, never the skulls or the orrery - and it staggers him, open. He can be hit as he steps into a ring, and while he channels his skulls or his orrery. Guard or fly from fire and ice, leave the lightning mark, keep out of the poison, out-fly the death hand. A DEATH MARK that finds no one comes back on him. His RINGS work both ways: dodge through the one he opens by you and come out beside him, open. Of two rings, only one holds the desert. Burning, he fights ring to ring. At three quarters, half and a quarter he tears a portal into a realm of his spells - fire, ice, poison - where his ward holds until you find its opening. His BONE STORM rings you with skulls: fly out through a gap. Wounded, his ECHO casts each spell twice; burning, THE GRAVE drags your carpet toward its void. His WARD turns every blow until an opening breaks it. His ORRERY swings worlds round him; his GRAVE SCRIPT burns every line of the sky but one.'},
  { t: 'burieddead', name: 'THE BURIED DEAD',sub:'the whole grave wakes',desc:'Jump the marked slam or climb a grave shelf. Guard the arm sweep. Follow the moving shadow, then leave the bright crack before he erupts. Cut down the zombies he calls. Wait on a ledge or far off and he throws a lit skull: guard it. When the earth cracks in a line towards you the GRAVE HANDS follow it: jump them, or stand in the light of a burning vent, where the dead cannot rise. Light a vent under him and the gas opens him. At half health his slam reaches farther, more dead answer, and his GRAVE BREATH puts out every fire in the room, yours too: take fire again from the candles at the walls.' },
  { t: 'corpse', name: 'THE FALLEN', sub: 'the battle is still being fought', desc: 'A soldier of a war nobody buried. It lies where it fell until a banner stands over it, then it gets up and cuts - guard it. Cut down under a banner it only falls again: strike it while it lies there, or burn it, and it stays down.' },
  { t: 'duneworm', name: 'THE DUNE WORM', sub: 'the caravan\'s grave keeps its keeper', desc: 'He hunts under the hollow\'s sand: a ripple runs at you and bursts up where it locks - step off it late. Up, he blasts sand from his mouth (a shield takes it), coils and lunges where his shadow falls, opens the sand under you (jump, and keep jumping), and sweeps his tail along the floor: jump it. His hide turns every blade. Ledges of the old town rise from his sand: stand by one when he comes and he hits his head on it - stunned, he can be cut. At half he calls the storm.' },
  { t: 'scorpion', name: 'THE DUNE SCORPION', sub: 'two answers in one shell', desc: 'Up close it lifts a claw - a yellow mark, and a shield turns it. Stand a little further off and the tail comes up over its back instead - a red mark, and nothing turns that: step out of it, then walk in and cut while the tail comes down.' },
  { t: 'sandgob', name: 'THE SAND GOBLIN', sub: 'a mound with eyes', desc: 'Buried, it is only sand and two eyes, and a blade goes straight through it. Walk past and it rises with the sand pouring off - that is the tell - and cuts twice with a knife a shield turns. Then it goes under and comes up again ahead of you.' },
  { t: 'banditmystic', name: 'THE BANDIT MYSTIC', sub: 'he chants to free it', desc: 'A man of the Gang Leader\'s band in the dust-red robe of the old waterworks\' keepers, hooded and wrapped to the eyes, a sun with a shackle through it stitched on his chest. The mystics went under the Kasbah to the binding works and chant at the seals to free what is bound at the bottom of the well. He keeps his distance: a fist of sand held out is a SAND BOLT (a yellow mark - strike it back, or take it on a shield), both hands up is a rune of sand under your feet (a red mark: step off it). A blow while he winds up throws him off.' },
  { t: 'sanddjinn', name: 'THE SAND SPIRIT', sub: 'a lesser djinn', desc: 'A little whirl of sand with a bald head, a topknot and two burning eyes - the Djinn of the Great Well in small, loosed as the mystics crack his seals. A blade passes straight through it. Pour your skin on it and it turns to MUD: it drops to the floor and crawls, and now a blade cuts it. Leave it and it dries and whirls up again. It drifts, flares white (a red mark) and darts - only the dart hurts.' },
  { t: 'firedjinn', name: 'THE FIRE SPIRIT', sub: 'a lesser djinn, alight', desc: 'The sand spirit\'s burning brother, coal-dark under its flames, met deeper in the works where the Djinn\'s fire leaks up through the floor. Its fire turns a blade. Pour on it and it is DOUSED - grey clay and smoke on the floor - and a blade cuts it, until it catches again. It flares white (a red mark) and darts: only the dart hurts.' },
  { t: 'lampbearer', name: 'THE LAMP-BEARER', sub: 'his light wards them', desc: 'The mystics\' lamp-bearer, taller in the hood, a brass lamp held out on a pole. Its WARDING LIGHT is a warm circle on the ground, and every mystic and bandit standing in it wears a little lamp over his head: your blows land half on them. He is not warded himself. POUR your skin on the lamp and it goes out; or kill him - the lamp falls, still lit and still warding, and you can take it up (INTERACT) and throw it (ATTACK): it bursts where it lands and the floor burns under whoever stands there. He lifts it high to throw its fire at your feet: a red mark, step off.' },
  { t: 'firescorpion', name: 'THE FIRE SCORPION', sub: 'it leaves the ground burning', desc: 'A scorpion of the Well Town\'s ovens and alleys, its shell banded like coals. The claw and the tail come as any scorpion\'s - a yellow mark for the claw, a red one for the sting - but where the sting lands the ground catches, and it burns where it dies too. Stand in the fire and it bites you every moment: step out of it, or pour your skin on it. Water puts it out.' },
  { t: 'venomscorpion', name: 'THE VENOM SCORPION', sub: 'of the Cistern Queen\'s brood', desc: 'A green scorpion out of the dry cisterns. Its sting (a red mark) carries the Queen\'s venom: each one that lands puts a drop of it in you, three at most, and while it is in you your stamina comes back slower. Step out of the sting, and fight it with your stamina full.' },
  { t: 'oilscorpion', name: 'THE OIL SCORPION', sub: 'it bleeds lamp oil', desc: 'A tar-black scorpion out of the Underwell\'s old oil works, its shell slick with the oil it lives in. Its claw and sting come as any scorpion\'s - a yellow mark, a red one - but where the sting strikes, and where it dies, it leaves a SLICK OF OIL on the floor, and a slick burns like any oil. Kill it off the oil you mean to cross.' },
  { t: 'dustscorpion', name: 'THE DUST SCORPION', sub: 'grit in your eyes', desc: 'A pale scorpion the colour of the silt it hides in. When its claw comes up (a yellow mark) it flicks grit off the floor with it: if the claw lands, the grit is in your eyes and the dark closes in for two seconds. Its cloud also smothers burning oil a few steps ahead of it, one cell at a time: a thin firebreak will not stop it for long - pour a deep one, or kill it first.' },
  { t: 'thirstscorpion', name: 'THE THIRSTY SCORPION', sub: 'it smells your water', desc: 'A bleached scorpion dried half to bone in the Underwell\'s dry cisterns. It smells the water in your skin from far off and comes for it fast, and a sting that lands drinks a sip of it. Spend your skin where it matters before it reaches you, or cut it down first.' },
  { t: 'oilthief', name: 'THE OIL THIEF', sub: 'a lantern and a flask of lamp oil', desc: 'A tomb-robber who strips the Underwell\'s old oil works, a lantern at his belt. He keeps his distance, holds a flask up (a red mark: get out from under it) and throws it where you stand: it breaks into a pool of LAMP OIL, and lamp oil burns. His coat is soaked in the same oil - throw a torch onto the oil he stands in and the fire takes him twice as hard. Kill him and his lantern falls into his own spill.' },
  { t: 'cisternbat', name: 'THE CISTERN BAT', sub: 'it hates the light', desc: 'A pale bat that roosts in the dark vaults over the old cisterns. While you walk in the dark it drops on you - a yellow mark first: the shield turns it, and a blocked bat is swatted. Light scatters it: a torch in your hand, burning oil, a lit cresset. Carry fire under its roost and it will not come down.' },
  { t: 'gobrider', name: 'THE CART GOBLIN', sub: 'an archer on a rusty cart', desc: 'A mine goblin with a lit candle in his iron cap, riding a cart on the line beside yours. A red mark, then an arrow - it carries the pace of the cart: duck it, jump it, or knock him off the cart with any blow. Land in his cart and it is yours.' },
  { t: 'foremancart', name: 'THE FOREMAN', sub: 'a goblin in an armoured ore cart', desc: 'The foreman of the Deep Rails rides an iron-lidded ore cart round an endless loop of the Flooded Run, shuttling ahead of you. A blade on his cart only clanks. JUMP ON HIM: land on his cart from above and you stand on it while he is OPEN - strike him - until he LURCHES (a told rock of the cart) and throws you back into your own. Watch his tells: his brake shoes glow and he SLOWS (he drops back at you), his arm goes back for a PICK thrown where your cart will be, and red shoes mean a RAM: brake out of its reach, or jump. After a stomp his lid SPIKES come up for three seconds: do not land on them.' },
  { t: 'gobcaster', name: 'THE TUNNEL SHAMAN', sub: 'a rune-layer on a dark cart', desc: 'A soot-robed goblin shaman with a violet book and a lamp on his hat. He lays a rune on YOUR rail, ahead of where your cart will be when it bursts: boost or brake off it, or jump as it goes. Any blow throws him off his cart.' },
  { t: 'drowneddead', name: 'THE DROWNED DEAD', sub: 'the cistern keepers, still at the water', desc: 'The old cistern keepers, drowned when the water went bad, lying under the standing water of the Drowned Cistern. The water stirs before one rises. It grabs (a yellow mark) like any of the dead. FIRE TAKES THEM: a thrown torch or burning oil does three times the harm a blade does.' },
  { t: 'skitter', name: 'THE SKITTER', sub: 'the crack swarm', desc: 'A dog-sized crawler of violet glass, red-eyed, poured out of the cracks of the Glass Sea from dusk on - one is nothing, six are a fight. It runs at you and nips (a yellow mark: a shield turns it). IT WILL NOT STEP INTO FIRELIGHT: a campfire, or a fire\'s light thrown down onto its crack with a mirror, holds the whole swarm back.' },
  { t: 'glassscorpion', name: 'THE GLASS SCORPION', sub: 'lightning-glass with a sting', desc: 'A scorpion of fused green glass. Its claw and sting come as any scorpion\'s - but a SUN BEAM on its glass DAZZLES it still for a moment, and when it dies it SHATTERS into a patch of shards that cuts whoever walks through it.' },
  { t: 'shardthrower', name: 'THE SHARD THROWER', sub: 'he flings the glass', desc: 'A glass-cutter of the sea who keeps to a ridge and slings shards of glass at whoever is busy below him - turning a mirror, crossing a crack. His mark is a red cross where it lands: step off it.' },
  { t: 'nighthunter', name: 'THE NIGHT HUNTER', sub: 'it moves only in the dark', desc: 'A pale thing of the Glass Sea\'s nights, quick with a knife. In the dark it stalks and cuts; IN FIRELIGHT IT FREEZES where it stands. Fight it by a fire, or throw a fire\'s light on it.' },
  { t: 'glasssentinel', name: 'THE GLASS SENTINEL', sub: 'a wall of green glass', desc: 'A guard behind a shield of bottle-green glass that turns every blow from the front. Go round him, or come down on him from above.' },
  { t: 'greatdrill', name: 'THE GREAT DRILL', sub: 'a goblin in a drill rig', desc: 'A goblin drives the great rig down an endless tunnel, boring on ahead of you. Its cab is ARMOURED: a blow only dents it. When its chute rattles, its POINTS LEVER comes down the tunnel - THROW IT and its own ore pours into its bare GEARS: JAMMED, and its cab is open (miss it, and you can still RAM the ore cart it kicks off its back). Its driver lobs DYNAMITE onto your line, it BACKS AT YOU, it SPINS UP and lunges at head height (duck in your tub), it hooks your cart on a CHAIN (jump, or cut it), and at the last it brings the ROOF down.' },
  { t: 'colossus', name: 'THE GLASS COLOSSUS', sub: 'the giant at the edge of the sea', desc: 'A giant of lightning-glass rooted in the steps it was made of. Its SUN LANCE runs along the ground: BAIT IT INTO A MIRROR that faces it and the light comes back into its chest and cracks it open. Its knees can always be cut, until they glaze. CLIMB ITS HOLDS to the cracks - and when it says HOLD, grip (DOWN) or be thrown. By night its swarm pours from the crack under it: turn a mirror TO THE FIRE and the firelight holds them, and its shoulders blaze. At dawn, a mirror TO THE SKY throws the sun on its crown.' },
  { t: 'spitscorpion', name: 'THE SPIT SCORPION', sub: 'it spits venom from its perch', desc: 'A purple scorpion that keeps to a high perch and lobs a glob of the Queen\'s venom at you - its tail curls up first and a red line shows where the glob will land. A glob that lands puts a drop of venom in you, and your stamina comes back slower. Climb to it: up close it only has its claw.' },
  { t: 'sandworm', name: 'THE SANDWORM', sub: 'a ripple in the riverbed', desc: 'A blind worm of the dry riverbeds, kin to the Dune Worm. It is a hump in the sand that runs at you, and a blade finds only sand. Then it stops, and the sand domes up on the spot (a red mark): be off it, for it comes up there with its jaws open. Up and swaying it is open - cut it before it goes back down, and comes up again ahead of you. The flood\'s horn drives it deep.' },
  { t: 'shieldguard', name: 'THE SHIELD GUARD', sub: 'a door with legs', desc: 'A gorge bandit behind a round shield of hide and iron, and it turns every blow from the front. He brings it round slowly: get behind him and cut, break it with a heavy blow, or come down on him from above. Tucked behind it (a yellow mark) he shoves you off your feet. Where he guards a bomber, he plants himself between you.' },
  { t: 'dynamiter', name: 'THE DYNAMITE BANDIT', sub: 'a lit stick and a strong arm', desc: 'A gorge bandit with a bandolier of red sticks. He lights one and holds it high, spitting (a red mark: nothing turns a blast), then throws it where you stand. It lies there fizzing inside a red ring: be out of the ring when it goes. Running water puts a fuse out - in the gorge, a stick thrown into the flood\'s road only hisses.' },
  { t: 'waterthief', name: 'THE WATER-THIEF', sub: 'he cuts your skin and runs', desc: 'A cutthroat of the Well Town in the wells\' blue. He feints like one (a half-raised blade and a stamp, no mark) and then cuts for real (a yellow !, a shield turns it). When his cut lands it opens your water-skin and he RUNS with the sip for a well. Catch him and cut him down and the sip is back.' },
  { t: 'gobscout', name: 'THE GOBLIN SCOUT', sub: 'eyes of the canopy', desc: 'The goblin archer in a leaf-green hood and a pale root bow, a red feather in it: the same arrows, the same shield answer. He holds the high roots and the lookout. On the lookout, strike his arrow back through the rope.' },
  { t: 'rootweaver', name: 'THE ROOT WEAVER', sub: 'bark and honey', desc: 'The weaver grown into the roots: bark-brown, honey-eyed, spitting the same web that holds your feet. Cut the curtain it hides behind.' },
  { t: 'rootspider', name: 'THE ROOT SPIDER', sub: 'bark-brown, amber-backed', desc: 'The bough spider in the roots colours. It hangs on its thread over the road and drops when you walk under it: hit it as it climbs.' },
  { t: 'rootlurker', name: 'THE ROOT LURKER', sub: 'an amber cap', desc: 'The lurker grown into the root-cap: scenery until you pass, then a lunge. Walk, do not run, under the amber caps.' },
  { t: 'stiltwalker', name: 'GOBLIN STILT-WALKER', sub: 'the lookouts of the fen road', desc: 'A goblin lookout on tall stilts with a long gaff, who keeps the gaff\'s length off you. He draws it up over his head and drives it down at your head and shoulders: duck under it, or parry it. His stilts are his weakness - a low sweep, a slide or a heavy blow from the ground cuts one and he topples, broken for the finishing blow. Some carry a horn: if he sees you he winds it, and if it sounds his crew comes.' },
  { t: 'bogtroll', name: 'THE BOG TROLL', sub: 'the brute under the fen road', desc: 'The goblins\' hired brute, who lives under their boardwalk and feels your weight on the boards. Bubbles, then a bulge under you that follows you and sets red: step off it, he bursts up through the boards. Lure that burst under a rotten section and the rotten boards give way round him - stuck to the chest, every blow lands double. Out of the water his peat hide turns most of a blow. Jump or roll the arm he sweeps along the boards to drag you in, and step off the ring of his peat. At half he rips the road away: three islands of boards over the biting water.' },
  { t: 'trophyhunter', name: 'GOBLIN TROPHY-HUNTER', sub: 'the goblins of the rootway', desc: 'A goblin in a hide cape with a bone-tipped spear, who rides a hoist down onto whoever passes under it - the rope creaks and he shows a yellow ! first. Cut the hoist\'s rope while he hangs and he falls dazed. On his feet he lunges from afar and jabs up close: a shield turns both.' },
  { t: 'huntmaster', name: 'THE GOBLIN HUNTMASTER', sub: 'the master of the hunt', desc: 'A lean goblin in a trophy mask with a great bow. Between his shots he holds the bow across him and turns a blow from the front: GO ROUND him, or cut him from a jump. His GOLD arrows can be STRUCK BACK - one that flies home breaks his quiver strap, then his bracer, then his MASK, and each break leaves him open. His RED arrows are poison: dodge them, never strike them. Cut a hoist\'s rope while he stands under its cage. Later he shoots the cage over YOU.' },
  { t: 'kiterider', name: 'GOBLIN KITE-RIDER', sub: 'the goblins of the sky road', desc: 'A goblin in a harness under a war-kite, circling at the top of a thermal. He swoops on a yellow ! down a line he shows you first: a shield turns it and knocks him out of the sky. Any blow while he flies cuts his line and down he comes, to fight on his feet - or into the cloud sea. A cloud on his thermal and he sinks to the rock. The horn of a hornblower calls him down on you.' },
  { t: 'raptor', name: 'THE CLIFF RAPTOR', sub: 'it keeps the bridges', desc: 'A rust-red bird of the gorge that circles over a bridge. When it picks you its eye goes red and its shadow snaps onto your spot (a red mark: no shield turns it) - then it stoops there. Leave the mark. It lands where it struck and is open on the ground a moment. It only hunts near the bridge it keeps.' },
  { t: 'matriarch', name: 'OLD PLUME, MATRIARCH', sub: 'the nest by the old dam\'s spillway', desc: 'The mother of the gorge\'s raptors, twice a man\'s height. She pounces where you stand (!!: a late roll), rakes twice up close (!: a shield turns it - roll out of it and she follows the roll, !!), sweeps her tail low (!!: jump it), kicks scree (!!) and screeches for her brood. Her talons turn a blow from the front: go round, or hit from above. A sluice lever lets the dam go: caught in the channel she leaps for a pillar, and a narrow one throws her. On the walls she dives at her shadow\'s mark, perches on the rope bridges (strike a post) and calls her young off the nest - kill them and she drops to them. When the dam cracks she rides the surge: get off the edge the foam runs to; every narrow pillar she lands on throws her.' },
  { t: 'hourglassking', name: 'THE HOURGLASS KING', sub: 'the buried city\'s last king', desc: 'The city\'s last king, who had himself made into clockwork so his hour would never end. His chest is an hourglass: his brass turns most of a blow while it runs, and when it runs empty he turns himself over. AS HIS GLASS RUNS LOW, PULL ONE OF THE THRONE ROOM\'S SAND-GATES: it takes his last grains, drags him to the gate and he STALLS - strike then. The sands rise at his walls, and at the last his glass cracks and runs faster.' },
  { t: 'tombking', name: 'THE COFFIN KING', sub: 'in his walking sarcophagus', desc: 'A man-sized coffin of stone that walks on stone legs, with the old king sealed inside. His lid turns most of a blow. THE TOMB IS A MACHINE: strike a wall switch when he walks into its sweep and the counterweight tips him onto his back - the lid flies off and he is open; later the floor plates arm, and a trap that lands on him (or a plate he stands on) does the same. He leaps onto any platform you stand on too long, reels you in on a chain, throws his lid along the floor, calls the dead out of the floor, rolls the length of the room and marks your spot with a curse of falling sand.' },
  { t: 'scarabmother', name: 'THE SCARAB MOTHER', sub: 'the brood-queen of the sealed tomb', desc: 'The queen of the tomb\'s scarabs, grown fat on the robbers who came for its gold. Her shell turns most of a blow. LURE HER INTO A TRAP\'S REACH AND TREAD ITS PLATE: the block pins her, the darts stick in her joints, the stone flips her on her back - strike then. She charges at where you stood and stops a body short of it: wait by a plate\'s far side. Her brood comes up out of the cracked floor, and at the last she shakes stones down from the roof. Crowd her - stand on her ledge or in one spot too long - and she leaps onto you, or burrows up under you.' },
  { t: 'mummy', name: 'THE MUMMY', sub: 'the tomb\'s dead', desc: 'The tomb\'s dead, wound in their linen and set to walk the galleries they were buried to guard. It lashes a bandage (a shield turns it) and lunges to GRAB (strike it to tear free). IT IS HEAVY: its tread fires a trap\'s plate as surely as yours. ITS LINEN BURNS.' },
  { t: 'tombskel', name: 'THE TOMB GUARD', sub: 'the bones of the old guard', desc: 'The tomb\'s old guard, its linen long rotted off: it climbs out of its tomb when the lid cracks. A short CUT (a shield turns it) and a LEAP-CHOP from a crouch (step out of it). IT IS LIGHT: its bones do not press a plate, so it walks the reaches unharmed until you fire them.' },
  { t: 'dartblower', name: 'THE TOMB DART-BLOWER', sub: 'a priest of the dead', desc: 'A priest of the tomb in his linen, with a blowpipe: he keeps to the shelves and the walks and blows darts down at you while you work the plates.' },
  { t: 'jackal', name: 'THE TOMB JACKAL', sub: 'the dog of the dead', desc: 'Black, gold-collared and quick: it runs at you and leaps low at the last stride. Light on its feet - it never presses a plate.' },
  { t: 'scarab', name: 'THE SCARABS', sub: 'her brood', desc: 'The Scarab Mother\'s brood, out of the pits in a swarm. One blow kills one. Too light to press a plate.' },
  { t: 'construct', name: 'THE CLOCKWORK CONSTRUCT', sub: 'the city\'s old watch', desc: 'Brass plates on an iron frame, a halberd and a winding key: the Buried City\'s watch still walks its rounds. It pokes twice (a shield turns it) and then sweeps low (jump it). SAND IN ITS GEARS JAMS IT: moving sand under it - a room filling or draining - and it stands slumped and takes a blow twice over.' },
  { t: 'sanddrowned', name: 'THE SAND-DROWNED', sub: 'the city\'s dead', desc: 'The city\'s people, drowned in the sand when it came in. They lie in the drifts and rise as you pass, and their grip is heavy.' },
  { t: 'sandbound', name: 'THE SAND-BOUND', sub: 'the drowned the sand kept', desc: 'One of the drowned that the sand grew over like a shell. While its hourglass rests the sand holds it, and a blade glances off. Turn the glass and it is buried to the chest - stuck, and every blow lands.' },   /* (claude/buriedcity4) */
  { t: 'sandslinger', name: 'THE SAND-FOLK SLINGER', sub: 'the city\'s last folk', desc: 'A slinger of the few who still live in the buried streets. From a balcony he marks your spot with a red cross and his stone falls there: step off it, or take it on the shield.' },
  { t: 'brassscorpion', name: 'THE BRASS SCORPION', sub: 'the city\'s clockwork vermin', desc: 'A scorpion of tarnished brass, wound by no one and still running. Its sting is heavy for its size.' },
  { t: 'hawkmistress', name: 'THE HAWK-MISTRESS', sub: 'chief of the bandit ksar', desc: 'The raiders\' chief and falconer: a whip, a curved knife, a bandolier of knives and the fort\'s powder. HER HAWK IS HER SHIELD: while it rides over her a blow barely bites. Take a torch from a brazier (or a keg from the stack) and throw it into the hawk - it comes down burning, and she is OPEN. A gong sends it wheeling low; a stoop struck or shielded sends it off. Her guard answers the gongs: cut their ropes. When the powder store burns, the roofs go.' },
  { t: 'paladinboss', name: 'THE PALADIN', sub: 'sworn to the light', desc: 'The Paladin\'s own kit, and he fights like you: the war hammer, conviction, his hallowed aura. His LIGHT-WARD turns a blow from any side and feeds him - hit him while he swings. His three BRAZIERS stand dark: carry a flame and light one BESIDE him and the fire breaks his ward - he FALTERS. Lit far off, he prays at it. Later he snuffs them. HAMMER (!) and SMITE (!) a shield turns. SPEAR (!) jump it. RADIANCE (!!) get out. SUNFALL (!!) between the lights. Later VERDICT (!!) keep moving, and DAWNFALL (!!) off the ring.' },
  { t: 'priest', name: 'THE PRIEST', sub: 'strong in his own light', desc: 'The church\'s clergy, in a cream alb and a gold stole. A told LIGHT BOLT (! a shield takes it, a blade sends it back) and a sigil under your feet (!! step off). He PRAYS over his own (a gold glow, no mark: a blow cuts it). Lit, his room makes him strong - x1.3 on his bolts, half again on his prayer; dark, he is weak. He walks to a snuffed lamp and RE-LIGHTS it: kill him first.' },
  { t: 'thurifer', name: 'THE THURIFER', sub: 'the censer-bearer', desc: 'A server of the church in a white cotta, swinging a censer. Across the room he lobs it (! a shield turns it); hurt clergy near him, he raises it over them and they mend (a blow on the windup breaks the rite). In a lit room he is strong, in a dark one weak.' },
  { t: 'bellringer', name: 'THE BELL-RINGER', sub: 'the hand bell', desc: 'A ringer in a black cassock with a hand bell. In your face he rings it into you and shoves you back (! a shield turns it); he blesses his own with the censer\'s rite too. A lit room makes him strong.' },
  { t: 'archdeacon', name: 'THE ARCHDEACON', sub: 'the priests\' captain', desc: 'The south transept\'s elite in a violet cope. His prayer reaches his whole room - deep while it is lit. Snuff his lamps and it is thin, but the dark lets the dead up through the grates. He holds the way to the sanctuary.' },
  { t: 'acolyte', name: 'THE ACOLYTE', sub: 'he runs with a taper', desc: 'A boy of the choir in a red cassock and a white surplice. He does not fight. Snuff a lamp in his room and he runs for it with his taper and lights it in a breath: catch him.' },
  { t: 'chapelknight', name: 'THE CHAPEL KNIGHT', sub: 'the priests\' escort', desc: 'A sworn sword in the church\'s white. One cut, a long tell: take it on the beat and he is open. In a lit room he hits a little harder.' },
  { t: 'templar', name: 'THE TEMPLAR', sub: 'the poleaxe at the door', desc: 'A hedge knight in the church\'s white and gold: the poleaxe comes round (! and sometimes it is a feint), and the leap (!!) cannot be blocked.' },
  { t: 'chapelbow', name: 'THE CHAPEL CROSSBOW', sub: 'on the triforium', desc: 'A crossbowman on the nave\'s gallery. A bolt can be taken on a shield, and a shield sends it back.' },
  { t: 'fogknight', name: 'THE FOG KNIGHT', sub: 'at the end of the towpath', desc: 'An empty suit of old rust-black plate, and the fog of the locks inside it holding the shape of a man. He guards by STANCE: GUARDS HIGH (shield up) - hit him low; GUARDS LOW (sword planted) - hit him from a jump; FULL GUARD (the fog wrapped round him) - only a plunge breaks it. A lit lantern near him burns the fog out of the armour, and a swing bridge swung through him scatters it: either way the plate stands empty. The fog lunge goes through any shield: roll in its last beat.' },
  { t: 'hawkscout', name: 'THE HAWK SCOUT', sub: 'her birds on the walls', desc: 'One of the Hawk-Mistress\'s hawks, patrolling the Ksar\'s walls. In the open under it you are seen: it wheels over you and SHRIEKS, and every lookout who hears it runs for his gong; then it stoops on the spot it marked. A roof over you or smoke between hides you; a flash flask blinds it. Two blows bring it down.' },
  { t: 'gonglookout', name: 'THE GONG LOOKOUT', sub: 'he runs for the gong', desc: 'A Ksar lookout in an ochre scarf. He watches his stretch of wall; when he sees you (smoke hides you) he runs for his gong and rings it, and every bandit in its earshot comes. Cut the rope first, or catch him on his way.' },
  { t: 'ksarblade', name: 'THE KSAR BLADE', sub: 'the raiders\' curved swords', desc: 'The Ksar\'s raiders: a feint, then the real cut (a shield turns it). Every one of them answers the gongs - he leaves his post and runs to a gong that rings.' },
  { t: 'falconer', name: 'THE FALCONER', sub: 'one of her hawk-handlers', desc: 'A Ksar falconer with a hawk on his glove. He sends it at you (his arm goes back - step off its shadow when it stoops) and whistles it home. While it rides over him it guards him: a blow barely bites. Knock the hawk down - two cuts, a torch, a keg, or a flask to blind it - and he is open.' },
  { t: 'ksarplate', name: 'THE PLATED BANDIT', sub: 'the fort\'s steel', desc: 'A heavy raider in steel plate with a broad cleaver: slow, and every blow of his is the heaviest in the fort. A blade only clanks off the plate. Throw a powder keg at him (or catch him in a chain of them): the blast blows the plate off, and then he cuts like any man.' },
  { t: 'whipapprentice', name: 'THE WHIP APPRENTICE', sub: 'a junior falconer', desc: 'One of the Hawk-Mistress\'s apprentices. His whip reaches twice a sword\'s length, and a lash that lands pulls you in toward him.' },
  { t: 'shieldsentry', name: 'THE SHIELD SENTRY', sub: 'planted at his gong', desc: 'A sentry planted in front of a gong behind a great shield. He will not leave it, and when the alarm goes - or he sees you coming - he strikes it himself. Get round him, over him, or break his guard to reach the rope.' },
  { t: 'smokethrower', name: 'THE SMOKE THROWER', sub: 'pots of smoke', desc: 'He keeps his distance and throws clay pots that burst in thick smoke. No eye sees through it - not a lookout\'s, not a hawk\'s - so his smoke can hide you as well as him.' },
  { t: 'wallslinger', name: 'THE WALL SLINGER', sub: 'stones from the parapets', desc: 'A slinger on the Ksar\'s towers and parapets: a red cross marks where his stone will fall.' },
  { t: 'gorgecrab', name: 'THE GREAT RED CRAB', sub: 'the old dam at the head of the gorge', desc: 'A crab as wide as a cart, in a red shell no blade bites. His pinch a shield turns (!); his crush, his boulders (a red mark where you stand) and his low scuttle (to where you stood) it does not. The dam\'s sluice gate stands over the spillway: shut it (E at a wheel) and the next flood banks behind it; release it while he is in the channel and the water throws him on his back. He walks out of the channel at the horn. At half he smells the held water and only his scuttle carries him in.' },
  { t: 'gangleader', name: 'THE GANG LEADER', sub: 'the courtyard of the Kasbah', desc: 'The bandits\' captain: two curved swords and a sling of oil bottles. His cuts a shield turns (!); his whirl it does not (!!). Quick on his feet: he dashes in - POUR WATER and the mud slows him and pens him in (he will not step in it); a dash through it slips him, down and open. He lobs lit bottles: STRIKE ONE BACK and it flies home - he stands beating at the flames, open (blows land harder; a puddle puts him out). His fire catches you: your skin douses it. Once in a while he slips your blade and comes straight back with a riposte.' },
  { t: 'djinn', name: 'THE DJINN OF THE GREAT WELL', sub: 'the deep cistern under the old well', desc: 'The thing the whole town draws its water from: bound at the bottom of the well, shackles broken on both wrists, a whirl of sand from the waist down. A blade passes through sand - POUR WATER ON HIM and he is mud, solid, open. Then he catches fire: his heat sets you alight, his fire turns the blade - DOUSE HIM. After every opening he WARDS a few seconds (the sand hardens, he flares white-hot, a shroud of water): wait it out. At the last he takes the well: the hall floods, and the flood RISES OVER THE LEDGES and falls again (a foam line warns you), the floor deep while it is high; he moves through it, strikes up from below where the bubbles boil, and the well turns. The great bucket lies in the flood: strike the windlass (or the crank on the ledge) to WIND IT UP, and again to DROP IT while he stands under the shaft - it bails him out where he is, and you wade in to cut him - and strike his hand where it rests.' },
  { t: 'cisternqueen', name: 'THE CISTERN QUEEN', sub: 'the dry cistern under the Kasbah', desc: 'A scorpion the size of a cart, nested in the cistern she drank dry. Her raised claws turn every blow from the front. Her openings are all WATER: flood her burrow (pour on the mound, or bring the shaft\'s bucket down on it); when she clings to a wall, climb to its ledge and pour down the wall above her; when the cistern floods, break her grab - strike the claw. Her venom slows your stamina.' },
  { t: 'cutthroat', name: 'THE CUTTHROAT', sub: 'watch the mark, not the arm', desc: 'A veiled looter with a scimitar, and he feints: every other time he comes in, the blade half rises and he stamps - no mark, nothing behind it. Then the real one, high and back with a glint and a yellow mark, and a shield turns it. Hold your guard through the feint.' },
  { t: 'stagehand', name: 'THE STAGEHAND', sub: 'the crew never went home', desc: 'A crew brute in a leather apron with a sandbag on a line. When the sack goes up over his shoulder it comes down in front of him and nothing turns it: step back out of it, then cut him while he hauls it in. Stand over him - on a gallery, a balcony - and he hauls a line instead, and a sandbag drops from the flies onto where you stood: watch for the shadow under your feet. The theatre\'s own sandbags come down on him just as hard.' },
  { t: 'mummer', name: 'THE MUMMER', sub: 'do not turn your back', desc: 'A masked player in sackcloth with bells on his cap. He moves ONLY while nobody is looking at him: face him and he freezes where he stands, and a frozen mummer can be cut down in about three blows. Turn away and the bells jingle as he creeps up behind you. When his mask glows red he is at arm\'s length and about to strike: look at him. In two-player, he is frozen if EITHER hero faces him.' },
  { t: 'deadpaladin', name: 'UNDEAD PALADIN', sub: 'the order\'s fallen', desc: 'A paladin of the order, dead and still in his plate, under a CRACKED divine shield - blows bite through it, but only a little. Before his overhead a star GLEAMS on his shield: PARRY THAT BLOW and the shield shatters. Strike him with a flame in your hand and it cracks open too. SHIELD BASH (!) a shield turns it.' },
  { t: 'orderpaladin', name: 'ORDER PALADIN', sub: 'sworn to the light', desc: 'A paladin of the order under a whole divine shield: nothing gets through it. But before his overhead a star GLEAMS on his shield - PARRY THAT BLOW and the shield shatters, and he stands open a while. SHIELD BASH (!) a shield turns it.' },
  { t: 'deadpriest', name: 'UNDEAD PRIEST', sub: 'he serves the dark', desc: 'A dead cleric with a bone censer. He keeps off you and RAISES THE DEAD, MENDS them and SNUFFS the lights near him - more dark, more dead. A GRAVE BOLT (!) jump it. Bring a FLAME near him and he breaks off whatever he casts and flees. A blow cuts a cast.' },
  { t: 'fogwraith', name: 'THE FOG WRAITH', sub: 'the fog on the low water', desc: 'A shape of the fog that lies on the canal\'s low water - a hood and two long arms, no legs. It never leaves the fog: get above the bank and it is under you. Dim, it is only fog: it drifts through you with a chill and nothing you swing finds it. In your lantern\'s light, or a lamp\'s, it hardens - the edges sharpen, the eyes glow - and a blade cuts it. Close to a lit lantern it reaches for the flame (a yellow !): cut it while your light holds it, or it puts the lantern out.' },
  { t: 'grindylow', name: 'THE GRINDYLOW', sub: 'what lives under the towpath', desc: 'A weed-slick imp of the canal. Under the water it is only ripples and bubbles, and nothing you swing finds it. Stand at the edge over its water and it comes in under you: the water rings (a red !!), and then it has your ankle and pulls. Jump the ring, or strike it and knock the thing up out of the water; caught, shake it off - three quick presses - before it has you in the canal. Out of the water, dazed or left on the wall of a lock that drained away under it, it is weak.' },
  { t: 'willowisp', name: "WILL-O'-THE-WISP", sub: 'a lantern with no post', desc: 'A cold green light in the fog that bobs with nothing under it. Every lantern on the canal burns yellow and stands on a post; this does neither. Come near and it drifts on ahead of you as if it marked the way - off the bank, over the water, onto the weed. Close to, it gutters (a yellow !) and flares in your face. One blow and it pops. A foghorn\'s clear air shows it for what it is.' },
  { t: 'lampsnuffer', name: 'THE LAMP-SNUFFER', sub: 'the street goes dark behind him', desc: 'A night-warden in a black coat who is not hunting you. He walks the street putting the lamps out, one at a time, and the Reeve is glad of it. He swings the brass pole if you crowd him. Light what he snuffs, or cut him down and the lamps stay lit.' },
  { t: 'gravehound', name: 'THE GRAVE HOUND', sub: 'the Stair keeps its own', desc: 'Pale as the lawn it guards, and as quiet until the last stride. Runs straight at you and leaps low. Stomp it, swing as it lands, or put fire between you.' },
  { t: 'fireimp', name: 'THE FIRE IMP', sub: 'the first of his realms', desc: 'An imp that has been at the furnace of the Archmage: ember-red, a white-hot flame in its fist. It throws on a yellow mark, and where its fire lands the stones go on burning. Be off the ground it lands on, or take the throw on the shield.' },
  { t: 'venomimp', name: 'THE VENOM IMP', sub: 'the second of his realms', desc: 'An imp off the poison shelf of the Archmage, bottle-green with a green flame. It throws on a yellow mark, and what lands on you poisons: a slow drip of health until it wears off. Take the throw on the shield, or be elsewhere when it lands.' },
  { t: 'strongman', name: 'THE STRONGMAN', sub: 'ring the bell', desc: 'A fairground strongman in a striped singlet with a long-handled mallet, who has been ringing the high striker all season and has grown into it. Two tells, as the mallet does: a double mark is the overhead, which nothing blocks, so dodge it; a single mark is the sweep, which the shield holds. Hit him while the mallet is up, or while he blows.' },
  { t: 'bandit', name: 'BANDIT BOWMAN', sub: 'a rifle-man on the roofs', desc: 'A gorge-town bandit in a head-cloth with a short bow, who watches the street from a balcony or a gatehouse roof. He draws on a mark and looses: shield the shot, or get out of his line. A man, not a goblin: the Well Town has no goblins in it.' },
  { t: 'flyman', name: 'THE FLYMAN', sub: 'sandbags from the grid', desc: 'A stagehand on the flies, up where the ropes run, who has been told to bring the house down. He lobs a sandbag down onto you on a red mark that no blade turns: be off the ground it lands on. Cut him down or climb to him, and the grid is yours.' },
  { t: 'prompter', name: 'THE PROMPTER', sub: 'reads them their lines', desc: 'A man in black in the prompt corner, reading the cast their lines: while he reads, they mend and stand firmer. Cut him first. A fight with him alive is a fight against everyone he is reading to.' },
  { t: 'powderboy', name: 'THE POWDER MONKEY', sub: 'he has the kegs to light', desc: 'A powder-boy off the ships, in a navy jersey with a bandolier of red sticks, who is far too happy among the kegs. He lights one and holds it high, spitting (a red mark: nothing turns a blast), then throws it where you stand. It lies fizzing inside a red ring: be out of the ring when it goes. A stick that lands by a keg lights the keg, and the next, and the next: draw him away from the powder, or let him light it under the crew.' },
  { t: 'tidecrab', name: 'THE TIDE CRAB', sub: 'two eyes in the sand', desc: 'A mud-green shore crab that lies buried in the sand at low water with only its two eye-stalks showing, harmless and not to be hit, and comes up when the flood comes in. Surfaced it is a crab: claws up when you swing, a told ! before the pinch, over it goes if you land on its back. When the water drops it burrows again, and the eyes are all you will see. The stalks stand up and flick just before the sea turns.' },
  { t: 'shockeel', name: 'THE SHOCK EEL', sub: 'the water bites back', desc: 'An eel gone blue and bright from living by the old drowned wheels. It does not lunge. It hangs under you and charges (a red mark and a ring on the water that is its whole reach), then the ring goes off: everything swimming in it is shocked, and nothing turns it. A swimmer is the only thing it hurts: wade, hop the rocks, or be out of the ring before it goes.' },
  { t: 'navvy', name: 'THE NAVVY', sub: 'pick and candle', desc: 'A pitman in a flat cap with a candle stuck in it, who has been digging under the castle so long he no longer looks up. Digs through soft rock toward you and leaves the tunnel behind for you to use. Swings a pick with a slow, heavy tell: block it and he is open. Across a gap he THROWS it - and then he has nothing at all until he walks over and picks it up again. Drops his lamp when he dies, and the lamp stays lit.' },
  { t: 'bonechucker', name: 'THE BONE-CHUCKER', sub: 'it kept the rock', desc: 'Whatever dug in here first never left: bones in a ribcage of rags, a skull under the rock it carries, and a lantern it lobs from a distance and then nothing at all. The fire it throws is a problem and a favour at once. Close the distance and it has nothing.' },
  { t: 'timberman', name: 'THE TIMBERMAN', sub: 'he holds the mine up', desc: 'A pitman with a prop on his shoulder who does not want to fight you. He wants to get to the nearest set of timber and PROP IT, and while he is standing by one that set will not come down. Kill the timberman and then cut the timber; do it the other way round and you have done the work twice. He swings the prop itself, which is slow, wide and heavy.' },
  { t: 'minewarden', name: 'THE MINE WARDEN', sub: 'a bell on a company wage', desc: 'The mine company watch, in an ochre tabard and an iron hat, whose whole job is a bell. See him before he sees you: once he has you he runs for it, and a rung bell drops the gates of that working and turns out the garrison. Catch him on the way, or break the bell.' },
  { t: 'bargeman', name: 'THE BARGEMAN', sub: 'eight feet of boat hook', desc: 'A canal hand with a boat hook as long as a barge pole, and he uses it on whatever goes PAST him. Ride under his towpath and the hook comes down at the deck (a red !!): duck on the deck and it goes over you; a hook that lands takes you off her and into the water. Close in, he swings the haft.' },
  { t: 'riverrat', name: 'THE RIVER RAT', sub: 'out of the fog in a skiff', desc: 'One of a boarding gang that waits in the fog wall for a barge held at its edge. They come over her rail one after another and fight on her deck: a hook that throws you into the canal, and the haft up close. Keep to the middle of her and cut them down as they land.' },
  { t: 'deckforeman', name: 'THE DECK FOREMAN', sub: 'the basin is his', desc: 'The biggest man on the canal, and the lock door stays shut until he is down. He fights like a bargeman half as big again: the hook reaches further and lands harder. Deal with him in the dark, before a horn shows you to the bridge.' },
  { t: 'watchman', name: 'THE WATCHMAN', sub: 'a crossbow in the fog', desc: 'The night watch on the canal\'s bridges and roofs. In the fog he looses only at what is LIT: a lantern, the barge\'s lamp, a lamplighter beside you. Put the lantern out and pass him in the dark, or take the bolt on the shield.' },
  { t: 'lamplighter', name: 'THE LAMPLIGHTER', sub: 'kill him first', desc: 'He walks to every lantern you put out and lights it again, and the lantern on his pole shows you to every watchman near him. Cut him down before you douse the post.' },
  { t: 'hobbyhorse', name: 'THE HOBBY-HORSE', sub: 'it charges the moment you turn away', desc: 'A carved horse\'s head on a pole and a cloth skirt, and a player under it. The moment your back is turned it rears (a red eye, a bell) and CHARGES a long run in a straight line, and it will not stop for a look once it has begun. It stands where the charge ends and will not charge again until you have looked at it. Jump the charge, or climb a haystack out of its way. In two-player it charges only when BOTH heroes have their backs turned.' },
  { t: 'wickerman', name: 'THE WICKER MAN', sub: 'strike its fire back', desc: 'A tall effigy of woven willow stuffed with straw, built for the bonfire of the fair and walking off before it could be lit: a lesser echo of the Wicker Queen. Its feet move only while no one looks at it, but its arms never stop. It lights a bundle of its own straw over its head (two red marks) and bowls it along the ground: jump it, or STRIKE IT BACK - hold your blade, and swing as it rolls into your reach (it flashes white). Struck back, the fire rolls home and the wicker catches: cut it down while it burns, before it stamps the fire out. Anything else, the wicker shrugs off. Up close it brings both long arms down (one yellow mark): the shield takes it.' },
  { t: 'stringjack', name: 'THE STRING-JACK', sub: 'it moves only while you look at it', desc: 'A jointed wooden puppet on strings that run up into the dark. The rule the other way round: it moves ONLY while somebody is looking at it, and hangs limp the moment every back is turned. Looking at a mummer to hold it is looking at the marionette to bring it on. When it jerks (a yellow !) it is about to cut: take it on the shield, duck under it, or turn your back and the strings go slack. In the hall of mirrors the true glass looks behind you, and works its strings.' },
  { t: 'juggler', name: 'THE KNIFE JUGGLER', sub: 'he throws at your back', desc: 'A fairground juggler on a stall roof, three knives always in the air. He keeps the fair\'s rule: while you look at him he only juggles. Turn your back and he draws one down (a yellow !) and throws it flat and fast at where you are going. He stands where you cannot face him and the mummer he covers at once: climb to him, or keep moving.' },
  { t: 'shy', name: 'THE STALLHOLDER', sub: 'three throws a penny', desc: 'The coconut shy\'s man, up on his stall roof with a basket of coconuts. Looked at, he only tosses one from hand to hand. Turn your back and he lobs it where you are running to (its ring shows where it lands); a hard shy-ball (red !!) goes through a shield. Any blow puts him on his back.' },
  { t: 'barker', name: 'THE BARKER', sub: 'roll up, roll up', desc: 'The fair\'s caller, on his crate with a speaking trumpet. Every few seconds he raises the trumpet (you hear it drawn and see the rings go out) and CALLS: every hero in earshot is turned to face him and held that way a moment - off the mummers you were watching. Hit him while the trumpet is up and the call dies in his throat. Come too close and he swings his cane (a yellow !). Kill him first. In two-player his call turns you both.' },
  { t: 'lanterneater', name: 'THE LANTERN-EATER', sub: 'under the raft at the end of the fog canal', desc: 'Something enormous lives under the canal basin, and its lure is a FALSE LANTERN that glows in the fog like the basin\'s own lamps. Two lights come down over the raft: the real lamp FLICKERS, the lure SWAYS. Strike the lure HIGH (a jump attack, or up and strike) as it dangles and it is snagged, OPEN; leave it and the jaws come up under it (!!). Later it surfaces beside the raft, jaws open: sweep its gums LOW at the rail, and step out of its snap - its teeth stick in the timber. Last it snuffs every lamp and hunts your lantern: strike the lantern to dim it and it bites at copies of the light instead, but its lure comes only to a light that is up. A blow at the wrong height clanks: TOO LOW, TOO HIGH.' },
  { t: 'wickling', name: 'THE WICKLING', sub: 'a lamp-flame that walks', desc: 'A little living lamp-flame on a stub of grey wick-wax, drifting a hand over the stones of the drowned city. It goes from lamp to lamp and DRINKS them: it curls round a flame and the lamp gutters out, and it burns brighter for it. A flame in your hand is what it wants most - it flares (two red marks) and darts, and a touch takes your fire. Strike it, throw fire at it or let burning oil reach it and it SWELLS (two red marks) and BURSTS INTO FIRE: the oil in reach catches, the dead lamps in reach light, a tar net burns - and so does whoever stands in it. Burst it beside what you want lit, never beside yourself. In the dark you see only its flame.' },
  { t: 'wickerqueen', name: 'THE WICKER QUEEN', sub: 'the maypole green at nightfall', desc: 'She moves only while you look away, but her arms do not need your back: her ribbons and her long spear come even while you look. Duck the high lash and the high thrust, jump the low ones; when the boards burn, ride a horse. Jump the ribbons when they sweep the ring. With every back turned she leaps - to your back, the pole or a horse - and the landing is marked. Her burning wicker ball: hold your blade, then strike it back as it reaches you, and her own fire sets her alight. Or draw her across the green with your back turned and turn round while she stands on hot embers. Cut her while she burns. In the dark she raises wicker copies: hers is the crown that really burns, the ribbons that blow, the only shadow, and a copy freezes dead in your look. When the lanterns flare, the bonfire ring comes: find the dark gap, or ride a horse. In two-player either look holds her.' },
  { t: 'puppeteer', name: 'THE PUPPETEER', sub: "the main stage of the Maskwright's Theatre", desc: 'He hangs from his control bar over the stage and works a duo: THE HARLEQUIN, fast and weak, and THE BRUTE, slow and heavy. Wood turns a blade until a puppet is spent: after each blow its strings go slack and it shines gold, and then it can be hit or its strings cut - a cut limb goes limp and its attack is gone. From the flies he lets a sandbag drop onto a growing shadow, or sweeps a snare line across the stage. Drop both puppets and the chain falls off the lever: ride the batten up and he reels on the gallery - until he throws you back down, and the scene changes: a storm, the night, an inferno, the sea.' },
  { t: 'marionette', name: 'THE BRUTE', sub: 'a toy soldier half again your height', desc: 'Slow and heavy: a told chop no shield holds, a ground slam you jump, a grab you step out of - two or three of them and you are in trouble. After every swing he stands spent: hit him, or cut a string. The ARM string takes his chop and grab, the BACK string his slam.' },
  { t: 'acrobat', name: 'THE ACROBAT', sub: 'a tumbler on two strings', desc: 'He hoists it over you and lets it fall: its shadow on the boards is where. Re-strung, it learns to swing across the stage at head height - duck it.' },
  { t: 'harlequin', name: 'THE HARLEQUIN', sub: 'fast, weak, and never still', desc: 'Quick strings of jabs (block or step back) and a low kick (jump it); he darts round you and jumps a hero who stands still. Fragile: a few blows, or ONE cut of his string, drops him.' },
  { t: 'masterpiece', name: 'THE MASTERPIECE', sub: 'a wooden king twice your height', desc: 'Four strings from a great crossbar. Its hands can be cut from the boards with a jump; its head and its back only from the gallery, where their strings pass the catwalk. Cut all four and it falls - and takes him with it.' },
  { t: 'slinger', name: 'THE ROOFTOP SLINGER', sub: 'he owns the tops of the ruins', desc: 'He stands on a tower\'s top and stones the road. As the sling whirls, a red arc falls to the spot you stand on: step off it, or take the stone on a shield. Climb the tower to him and he is only a man with a sling - up close he can do no more than kick.' },
  { t: 'ambusher', name: 'THE SAND-CLOAK', sub: 'an ambusher under the dune', desc: 'Under his sand cloak he is a mound with two gold eyes, and a blade goes straight through. Walk past and he rises with the sand pouring off - that is the tell - and cuts twice with a knife a shield turns. Then he throws the cloak over himself and comes up ahead of you.' },
  { t: 'vulture', name: 'THE VULTURE', sub: 'it cools you while it hunts you', desc: 'It circles high over its patch of sand, and its shadow is shade. When it picks you its eye goes red and its shadow snaps onto your spot: move off the mark before it dives. On the ground it is open for a breath before it labours back up.' },
  { t: 'bannerbearer', name: 'THE BANNER-BEARER', sub: 'he carries what gets them up', desc: 'He walks his standard up to you and plants it, and the fallen round it rise. Guard his pole. Cut him and every man his standard raised lies down, and his stretch of the ridge stops firing.' },
  { t: 'barrowrider', name: 'THE BARROW RIDER', sub: 'the old order\'s last knight, and his horse', desc: 'Jump the ride-through: the ghost horse goes through you. Strike him as he passes and he is out of the saddle. Guard the trample and the grave-fire; step out of the lance line. When the horse falls apart, cut the bones crawling back to him.' },
  { t: 'deacon', name: 'THE DEACON', sub: 'the church\'s lamplighter', desc: 'He keeps the lamps with a long brass pole, a hook one end and a flame the other. He guards HIGH with it: hit him LOW (down and X) or from behind. His four lamps are his LIGHT - snuff them; strike a chandelier and it comes down, on him if he is under it. In the dark he gropes: strike then. POLE SWEEP (!) jump it. SNUFFER HOOK (!) a shield, or out of reach. Later the FLAME ARC (!!): holy fire along the floor.' },
  { t: 'bloodknight', name: 'THE BLOOD KNIGHT', sub: 'the order\'s last knight', desc: 'The Blood Knight\'s own kit, and he fights like you. Every blow lands whole, but he guards and slips the heavy he sees coming. Dodge his Cleave late and it sticks in the floor. Jump the Grip; guard the Coil or it heals him. Hit the ward from behind, or fill it and break it.' },
  { t: 'deathknight', name: 'THE REAPER', sub: 'the scythe the order left', desc: 'Close in under the Swathe. Jump the Reaping or stand on a tomb. Leave the mark the Passing leaves. Guard the short cut. Let his Reaping drag one of his own risen dead in: he cuts it, and he is open. Past half, what falls in his chapel gets up again - finish it on the floor.' },
  { t: 'zombie', name: 'ZOMBIE',sub:'earth in its hands',desc:'Moving soil warns before it rises. Guard its reaching hands or jump away. If caught, move, jump or strike to break the brief grab.' },
  { t: 'harbormaster', name: 'THE BREAKWATER WARDEN', sub: 'keeper of the sea gate', desc: 'Guard the anchor and harpoon. Jump the low surge; stay on the floor beneath the high surge. Leave the marked pressure columns. Each attack opens his helmet for a counterattack. At half strength he opens twin vents and calls the high tide.' },
  { t: 'bellcrab', name: 'THE DIVING BELL', sub: 'a shell salvaged from the drowned', desc: 'The pincer can be guarded. Rise above the red floor ring before its ballast lands. Leave the yellow pressure circle before it bursts. Cross above a red scuttle. The shell is shut: let a stone go over the valve on its crown and the bell VENTS, open. Near the end the bell cracks and the crab comes out, fast and soft.' },
  { t: 'bellguard', name: 'THE BELLGUARD', sub: 'a diver who never came back', desc: 'His yellow hook can be guarded. His red knell cannot: get outside its ring. The heavy helmet turns light cuts; a held blow or plunge dents it. He rests after ringing, and that is the time to close.' },
  { t: 'drownedking', name: 'THE DROWNED KING', sub: 'the last one he could spare', desc: 'He has been down here the whole time, and the tribute was never going to the goblins. In his own water he SWIMS: he circles, comes in close, and marks a line before he runs you down it. Be across the line with a pillar at the end of it and he goes into the stone, open. THE FALL marks the floor under you and sticks in it. THE UNDERTOW takes anything LIGHT; a stone in your hands holds. THE ANCHOR goes round at his height and a shield fouls it. Stand on his floor and THE SLAM runs along it. THE MAELSTROM turns his water round himself and no shield turns a current: stroke away from it, or dash out of it, and cut him while he holds himself still in it. And he can drink the hall: DROWNED BREATH bursts the air you were going to, so go to another one.' },
  { t: 'propman', name: 'THE PROPMAN', sub: 'he holds the mine up', desc: 'He does not want to fight you. He wants to get to the nearest set of timber and PROP IT, and while he is standing by one that set will not come down - he puts the blow back in it faster than you can take it out. Kill the propman and then cut the timber; do it the other way round and you have done the work twice. He swings the prop itself, which is slow, wide and heavy. The Overman does not wait to be reached: he throws timber.' },
  { t: 'clinger', name: 'THE CLINGER', sub: 'it waits on the wall', desc: 'Blind, pale, and flat against the rock of a shaft, where it looks like nothing at all. It has no interest in you on the ground. It commits when you are IN THE AIR beside it: it lets go, falls with you, takes hold, and rides you down - and what kills you is the floor, not the thing. Swing while it has you and it lets go.' },
  { t: 'prince', name: 'THE BURIED PRINCE', sub: 'forgotten under the hill', desc: 'A goblin prince they buried under the mine and then forgot, and he has not forgiven it. His ROYAL CUT is long, and a shield turns it: block it and he reels. He sinks into the floor and comes up under where you stood, and throws his crown - bareheaded, he bleeds. His roof is three slabs on timber: cut the post on HIS side while he stands under one and it swings down on him - PINNED, and every blow lands twice. His diggers come up to the winch to prop the roof again: kill them at it. Past half he breathes the lamps out, and in the dark he is SHROUDED: light them again. At the end the whole roof is coming down, on him as well as on you.' },
  { t: 'courtier', name: 'COURTIER', sub: 'still in attendance', desc: 'What is left of the prince\'s court. They claw up out of the tomb floor when he calls, slow and brittle. A clean blow breaks one, a heavy one throws it, and the roof coming down finishes all of them.' },
  { t: 'forgemaster', name: 'THE FORGEMASTER', sub: 'engineer of the deep', desc: 'Twice the smith. His iron turns half of every cut; a cart into him stuns him and a stunned smith takes it all, doubled. Cut a standing tub to send it, ride one at him, or cut the beam tub off its rail onto his head. He drags tubs to himself on a chain and hurls them. He rings the anvil and hammers fall where you stand. Half dead the furnace opens: a fire breath, and the floor plates glow before they burn. Strapped into a steam rig at the forge. Three things never stop: the hammer stamps the floor on a rhythm, carts roll through on the rail, slag drips from marked spots. He lunges on a piston, sprays scalding steam, and kicks carts at you. Ride a cart into his boiler, or burn it with embers, and it bursts: he is scalded and open. Past half his blood the lamps go out and the bats come.' },
  { t: 'owl', name: 'THE OWL REEVE', sub: 'lord of the crown', desc: 'Swoops head high along a told line: duck under her. Skims the boards at the ankles: jump her. A struck lantern burns two breaths: light one as she comes and she crashes into it, and it is spent - hit her hard while she lies there. Her wing beat blows you toward the drop and blows the lamps out: hold down to brace, or hold a rope. She coughs bone pellets onto marked boards: step off the marks. She shakes the high bough: step out from under its shadows. Cut a dead bough\'s peg while she is low beneath and it pins her. Past half her blood she drops lit lanterns on you as burning oil.' },
  { t: 'king', name: 'KING GORM UNDERLEAF', sub: 'lord of the court', desc: 'Three times the goblin. Rides a litter that four bearers can barely lift: cut them and the throne falls. Then the sceptre sweeps, the hand reaches for you and hurls you the length of the hall, cages drop from the rafters, and the court throws when he shouts. At the end he stands, the roof comes down where he walks, and he throws the throne itself.' },
  { t: 'chief', name: 'GOBLIN CHIEFTAIN', sub: 'lord of the stockade', desc: 'Red tells and a stamp: the club. Blue tells and a glint: sword and shield. Green: the bow. He swaps at the racks by the walls; break a rack and that weapon is out of the fight. The dais is beyond his club and sword, not his arrows or his leap. He swaps weapons every few swings. Club: dodge the slam and hit him while it is planted. Sword and shield: block his slash to parry it, or get behind the shield. Bow: parry the arrows back at him. Whatever he holds, when he crouches he is about to leap on you: move. HIS WAR HORN: when he stops to wind it, two blows on him silence it and he chokes, open; let it sound and his crew come in at the doors. HIS POWDER: with the club he heaves a lit keg - step off it, or strike it and it rolls back; a blast that catches him knocks him down, open. At his second wind he climbs his war tower on the dais and shoots and drops powder from it: up there blows half land. Cut both its lashings, or blow its legs with his own keg, and it goes over - he comes down in the wreck, open.' },
  { t: 'mother', name: 'THE MOTHER CAP', sub: 'root of the wood', desc: 'Strike the diamond-marked root, or grow a bud beside her and get off before her cap folds: it jams on yours. Either opens her heart; spring up and cut it. It closes after a hit, and the root rests ten seconds and moves. Take the shelves over floor roots, duck the spore sweep, leave marked columns. At half health: root columns and a spore burst.' },
  { t: 'harpy', name: 'CRAG HARPY', sub: 'diver of the cliffs', desc: 'Hangs in the wind above you, screams, and dives in a straight line. Block the dive and she hits the ground stunned: plunge her there. A sword hit sends her back to her perch.' },
  { t: 'goat', name: 'CRAG RAM', sub: 'the hill charger', desc: 'A wild ram of the scree. It charges and hops walls and ledges. Block the charge and it rears, turned and open for a moment.' },
  { t: 'troll', name: 'HILL TROLL', sub: 'boulder-thrower', desc: 'Slow, mossy, taller than a door. From range it hurls a boulder in an arc at where you are going: watch the shadow and the whistle. Up close it swats, heavy but blockable. Its hide is soft: the sword and the plunge both bite.' },
  { t: 'ram', name: 'THE RAM LORD', sub: 'lord of the fold', desc: 'His horns turn a blade from the front: go round him, or come down on him from above. Two overhangs lean out over his fold on dry-stone props: when he stands under one (its prop glints gold), knock the prop out and the cliff comes down on him - STUNNED, a gold ring, and your blows land double. Dodge his charge and he hits the wall: a shorter opening. After each he shakes it off and is WARDED a moment. Two-thirds down, the fold floor slides toward the wall and he banks off it; a third down, the cliff rains rock and he sweeps his horns all the way round - jump it.' },
];
