  for (let dy = -1; dy <= 2; dy++) for (let dx = -2; dx <= 2; dx++) { const gx = tx + dx, gy = ty + dy, i = gy * LW + gx;
    if (gx < 1 || gy < 1 || gx >= LW - 1 || gy >= LH - 1) continue;
    const t = L.grid[i]; if (t === T.CRATE || t === T.SHELF) { L.grid[i] = T.AIR; tileSpr[i] = null; } }
