}
// A CANNONBALL goes down the deck until it meets something. It is the only thing that gets through the
// Quartermaster's guard, and it does not care what else is in the way.
let balls = [];
function updateBalls(dt) {
  for (const b of balls) { b.t += dt; b.x += b.vx * dt;
    if (Math.random() < dt * 40) parts.push({ x: b.x, y: b.y, vx: -Math.sign(b.vx) * 40, vy: -10, life: 0.4, max: 0.4, col: '#9aa39a', size: 2, grav: -20 });
    for (const e of enemies) { if (!e.alive || e.harmless || b.dead) continue;
      if (Math.abs(e.x - b.x) > e.w / 2 + 6 || b.y < e.y - e.h - 4 || b.y > e.y + 4) continue;
      if (e.t === 'champion' && CHH) { if (CHH.onBall(e, b)) b.dead = true; else continue; }   /* THE ADMIRAL'S CHAMPION: the round shot knocks him flat (B14, the deck gun the Powder Ship teaches); in the air it passes under him */
      else if (e.maxHp) { b.dead = true; hurtEnemy(e, 45, b.x, false); }
      else { hurtEnemy(e, 999, b.x, false); b.through = (b.through || 0) + 1; if (b.through >= 6) b.dead = true; }
      burst(b.x, b.y, 12, ['#e8dcc0', '#9aa39a'], 90, 0.5); if (b.dead) break; }
    /* (claude/flotilla2) A ROUND SHOT AND A KEG (L.flot2.ballKegs): the ball blows a keg it meets on the deck - how THE POWDER SHIP's crate hatch is blown from across the deck */
    if (L.flot2 && L.flot2.ballKegs && !b.dead) for (const pr of props) { if (pr.t !== 'keg' || pr.gone || Math.abs(pr.x - b.x) > 10 || Math.abs(pr.y - 7 - b.y) > 14) continue; b.dead = true; pr.gone = true; kegBlast(pr.x, pr.y - 7); break; }
    // A ROUND SHOT AND AN IRON DOOR. This is checked before the wall test below, because the door IS wall.
    for (const pr of props) { if (pr.t !== 'bulkhead' || pr.open || b.dead) continue;
      const [sx0, sx1, sy0, sy1] = pr.span;
      if (b.x < sx0 * TS - 4 || b.x > (sx1 + 1) * TS + 4 || b.y < sy0 * TS - 4 || b.y > (sy1 + 1) * TS + 4) continue;
      b.dead = true; pr.open = true; pr.shake = 0.5;
      for (let y = sy0; y <= sy1; y++) for (let x = sx0; x <= sx1; x++) { const i = y * LW + x;
        if (L.grid[i] !== T.AIR) { L.grid[i] = T.AIR; tileSpr[i] = null; destroyed.add(i);
          for (let q = 0; q < 2; q++) parts.push({ x: x * TS + 8, y: y * TS + 8, vx: Math.sign(b.vx) * (60 + Math.random() * 200), vy: -50 - Math.random() * 90, life: 1.1, max: 1.1, col: Math.random() < 0.5 ? '#6a7078' : '#3e444a', size: 2, grav: 300 }); } }
      resolveTiles(); SFX.crack(); SFX.stone(); shakeCam(8); zoomKick(1.06, 0.25); rumble(200, 0.8);
      number((sx0 + sx1) / 2 * TS, sy0 * TS - 10, 'THE BULKHEAD IS DOWN', '#8fd160');
      burst(b.x, b.y, 20, ['#9aa39a', '#e8dcc0', '#6a7078'], 120, 0.7); }
    if (b.dead) continue;
    if (b.t > 2 || isSolid(Math.floor(b.x / TS), Math.floor(b.y / TS))) { b.dead = true; burst(b.x, b.y, 8, ['#9aa39a', '#e8dcc0'], 70, 0.4); SFX.stone(); }
  }
  balls = balls.filter(b => !b.dead);
}
// FINS in the foul water: they never come out of it, but they are the reason you cross on the ropes
function drawFins(cx, cy) {
  if (!PROP.flot) return;
  for (const p of (L.pools || [])) { if (!p.harm || p.fire || p.poison) continue;   /* nothing swims in a burning ditch, or in the Undercrown's poison */
    const y = Math.round(p.y - cy) - 4;
    if (y < -20 || y > VH + 20) continue;
    for (let k = 0; k < 5; k++) { const span = p.x1 - p.x0, ph = k * 1.7, sx = p.x0 + ((time * (18 + k * 7) + k * span / 5) % span);
      const x = Math.round(sx - cx); if (x < -30 || x > VW + 30) continue;
      const d = 1 + Math.sin(time * 0.7 + ph) * 0.35;
      g.globalAlpha = 0.55 * d; g.drawImage(PROP.flot.shark, x - 12, y + Math.round(Math.sin(time * 1.3 + ph) * 2)); g.globalAlpha = 1; }
  }
}
function drawBalls(cx, cy) {
  for (const b of balls) { const x = Math.round(b.x - cx), y = Math.round(b.y - cy);
