let mending = []; // { i, t }: tiles the world broke that come back
function mendTile(i) { if (L.grid[i] === T.AIR && grid0[i] !== T.AIR) { L.grid[i] = grid0[i]; tileSpr[i] = null; destroyed.delete(i); return true; } return false; }
